export const questions: Question[] = [
  { id: "y2in5-001", topicRef: "y2in5", topicTitle: "Integration by Substitution 01", difficulty: "Standard", questionText: "Use the substitution \\( u = x^2 + 1 \\) to find \\( \\displaystyle\\int x(x^2 + 1)^3\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "The chain rule run in reverse. Whenever the integrand contains a composite \\(f(g(x))\\) multiplied by (a constant times) the inner derivative \\(g'(x)\\), the substitution \\(u = g(x)\\) collapses the integral to a one-variable integral in \\(u\\)." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "x(x^2 + 1)^3 \\;=\\; \\underbrace{(x^2 + 1)^3}_{f(g(x))} \\cdot \\underbrace{x}_{\\propto\\,g'(x)}", explanation: "The bracket \\(x^2+1\\) is a composite raised to a power, and its derivative \\(2x\\) appears (up to a constant \\(\\tfrac{1}{2}\\)) as the outside factor \\(x\\). That is the classic inner-and-its-derivative pattern." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = x^2 + 1 \\;\\Rightarrow\\; \\displaystyle\\frac{du}{dx} = 2x \\;\\Rightarrow\\; du = 2x\\,dx \\;\\Rightarrow\\; x\\,dx = \\displaystyle\\frac{1}{2}\\,du", explanation: "Take the inner function as \\(u\\), differentiate, and rearrange so the bundle \\(x\\,dx\\) sitting in the integrand can be replaced wholesale." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int x(x^2 + 1)^3\\,dx \\;=\\; \\displaystyle\\int u^3 \\cdot \\displaystyle\\frac{1}{2}\\,du \\;=\\; \\displaystyle\\frac{1}{2}\\displaystyle\\int u^3\\,du", explanation: "Every \\(x\\) is gone: \\((x^2+1)^3 \\to u^3\\) and \\(x\\,dx \\to \\tfrac{1}{2}\\,du\\). Pull the constant outside via linearity." }, { stepNumber: 5, description: "Integrate in \\(u\\) using the power rule.", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int u^3\\,du \\;=\\; \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{u^4}{4} + C \\;=\\; \\displaystyle\\frac{u^4}{8} + C", explanation: "Standard power-rule antiderivative \\(\\displaystyle\\int u^n\\,du = \\displaystyle\\frac{u^{n+1}}{n+1} + C\\) for \\(n=3\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = x^2 + 1\\).", workingLatex: "\\displaystyle\\frac{u^4}{8} + C \\;=\\; \\displaystyle\\frac{\\left(x^2 + 1\\right)^4}{8} + C", explanation: "Always restore the original variable in an indefinite integral — the answer must be a function of \\(x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(x^2 + 1)^4}{8}\\right] \\;=\\; \\displaystyle\\frac{4(x^2 + 1)^3 \\cdot 2x}{8} \\;=\\; x(x^2 + 1)^3 \\;\\checkmark", explanation: "Chain rule recovers the original integrand exactly, so the antiderivative is correct." } ], finalAnswer: "\\(\\displaystyle\\frac{(x^2 + 1)^4}{8} + C\\)." } },
  // ── Algebraic substitutions ────
  { id: "y2in5-002", topicRef: "y2in5", topicTitle: "Integration by Substitution 02", difficulty: "Standard", questionText: "Use \\(u = x^3 + 2\\) to find \\( \\displaystyle\\int x^2\\left(x^3 + 2\\right)^4\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule packaged as a substitution. We look for a composite multiplied by (a constant multiple of) its inner derivative." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "x^2\\left(x^3 + 2\\right)^4: \\text{ inner } g(x) = x^3 + 2,\\; g'(x) = 3x^2", explanation: "The bracket is a composite and its derivative \\(3x^2\\) appears (up to the constant \\(\\tfrac{1}{3}\\)) as the \\(x^2\\) factor outside. Classic u-sub pattern." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = x^3 + 2 \\;\\Rightarrow\\; \\displaystyle\\frac{du}{dx} = 3x^2 \\;\\Rightarrow\\; du = 3x^2\\,dx \\;\\Rightarrow\\; x^2\\,dx = \\displaystyle\\frac{1}{3}\\,du", explanation: "Differentiate \\(u\\), then rearrange so the bundle \\(x^2\\,dx\\) appearing in the integrand can be swapped out cleanly." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int x^2\\left(x^3 + 2\\right)^4\\,dx \\;=\\; \\displaystyle\\int u^4 \\cdot \\displaystyle\\frac{1}{3}\\,du \\;=\\; \\displaystyle\\frac{1}{3}\\displaystyle\\int u^4\\,du", explanation: "Every \\(x\\) is gone: the bracket becomes \\(u^4\\) and \\(x^2\\,dx\\) becomes \\(\\tfrac{1}{3}du\\). Constants pull outside." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "\\displaystyle\\frac{1}{3}\\displaystyle\\int u^4\\,du \\;=\\; \\displaystyle\\frac{1}{3}\\cdot\\displaystyle\\frac{u^5}{5} + C \\;=\\; \\displaystyle\\frac{u^5}{15} + C", explanation: "Power rule with \\(n = 4\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = x^3 + 2\\).", workingLatex: "\\displaystyle\\frac{u^5}{15} + C \\;=\\; \\displaystyle\\frac{\\left(x^3 + 2\\right)^5}{15} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(x^3 + 2)^5}{15}\\right] = \\displaystyle\\frac{5(x^3 + 2)^4 \\cdot 3x^2}{15} = x^2(x^3 + 2)^4 \\;\\checkmark", explanation: "Chain rule recovers the integrand exactly." } ], finalAnswer: "\\(\\displaystyle\\frac{(x^3 + 2)^5}{15} + C\\)." } },
  { id: "y2in5-003", topicRef: "y2in5", topicTitle: "Integration by Substitution 03", difficulty: "Challenge", questionText: "Use \\(u = 2x + 1\\) to find \\( \\displaystyle\\int x(2x + 1)^4\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx,\\quad \\displaystyle\\int F(x)\\,dx = \\displaystyle\\int F(x(u))\\,\\displaystyle\\frac{dx}{du}\\,du", explanation: "Substitution can also be run with \\(x = h(u)\\): we replace every \\(x\\) and the \\(dx\\) in terms of \\(u\\)." }, { stepNumber: 2, description: "Why u-substitution fits — but with a twist.", workingLatex: "(2x + 1)^4 \\text{ is a composite, but the loose factor is } x,\\; \\text{not } g'(x).", explanation: "Here \\(g'(x) = 2\\) is a constant — so the outside factor \\(x\\) does NOT match. We must express \\(x\\) itself in terms of \\(u\\), then absorb everything." }, { stepNumber: 3, description: "Invert the substitution.", workingLatex: "u = 2x + 1 \\;\\Rightarrow\\; x = \\displaystyle\\frac{u - 1}{2},\\quad du = 2\\,dx \\;\\Rightarrow\\; dx = \\displaystyle\\frac{du}{2}", explanation: "Solve for \\(x\\) and differentiate to get \\(dx\\). Both substitutions are needed because \\(x\\) appears as a loose factor outside the composite." }, { stepNumber: 4, description: "Rewrite the integral entirely in \\(u\\).", workingLatex: "\\displaystyle\\int x(2x + 1)^4\\,dx \\;=\\; \\displaystyle\\int \\displaystyle\\frac{u - 1}{2}\\cdot u^4 \\cdot \\displaystyle\\frac{du}{2} \\;=\\; \\displaystyle\\frac{1}{4}\\displaystyle\\int (u - 1)\\,u^4\\,du", explanation: "Each piece replaced: \\(x \\to \\tfrac{u-1}{2}\\), \\((2x+1)^4 \\to u^4\\), \\(dx \\to \\tfrac{du}{2}\\). The two halves combine to a single \\(\\tfrac{1}{4}\\) out front." }, { stepNumber: 5, description: "Expand the bracket.", workingLatex: "\\displaystyle\\frac{1}{4}\\displaystyle\\int (u - 1)\\,u^4\\,du \\;=\\; \\displaystyle\\frac{1}{4}\\displaystyle\\int \\left(u^5 - u^4\\right)\\,du", explanation: "Distribute the \\(u^4\\) so we have a sum of power-rule terms." }, { stepNumber: 6, description: "Integrate term by term.", workingLatex: "\\displaystyle\\frac{1}{4}\\displaystyle\\int \\left(u^5 - u^4\\right)du \\;=\\; \\displaystyle\\frac{1}{4}\\!\\left(\\displaystyle\\frac{u^6}{6} - \\displaystyle\\frac{u^5}{5}\\right) + C \\;=\\; \\displaystyle\\frac{u^6}{24} - \\displaystyle\\frac{u^5}{20} + C", explanation: "Power rule on each term, then distribute the \\(\\tfrac{1}{4}\\)." }, { stepNumber: 7, description: "Back-substitute \\(u = 2x + 1\\).", workingLatex: "= \\displaystyle\\frac{(2x + 1)^6}{24} - \\displaystyle\\frac{(2x + 1)^5}{20} + C", explanation: "Restore the original variable in the final answer." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(2x + 1)^6}{24} - \\displaystyle\\frac{(2x + 1)^5}{20}\\right] = \\displaystyle\\frac{6(2x+1)^5\\cdot 2}{24} - \\displaystyle\\frac{5(2x+1)^4\\cdot 2}{20} = \\displaystyle\\frac{(2x+1)^5}{2} - \\displaystyle\\frac{(2x+1)^4}{2} = \\displaystyle\\frac{(2x+1)^4}{2}\\!\\left[(2x+1) - 1\\right] = \\displaystyle\\frac{(2x+1)^4 \\cdot 2x}{2} = x(2x+1)^4 \\;\\checkmark", explanation: "Differentiating the answer factors back to the original integrand, confirming both substitutions were handled correctly." } ], finalAnswer: "\\(\\displaystyle\\frac{(2x + 1)^6}{24} - \\displaystyle\\frac{(2x + 1)^5}{20} + C\\)." } },
  { id: "y2in5-004", topicRef: "y2in5", topicTitle: "Integration by Substitution 04", difficulty: "Challenge", questionText: "Use \\(u = \\sqrt x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{1}{1 + \\sqrt x}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "x = h(u) \\;\\Rightarrow\\; dx = h'(u)\\,du,\\quad \\displaystyle\\int F(x)\\,dx = \\displaystyle\\int F(h(u))\\,h'(u)\\,du", explanation: "When the variable change is more naturally \\(x = h(u)\\), invert and compute \\(dx\\) in terms of \\(du\\)." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\text{Integrand contains } \\sqrt x \\text{ algebraically — a non-polynomial root.}", explanation: "Setting \\(u = \\sqrt x\\) rationalises the integrand: every \\(\\sqrt x\\) becomes \\(u\\), turning a root expression into an algebraic one in \\(u\\)." }, { stepNumber: 3, description: "Invert and compute \\(dx\\).", workingLatex: "u = \\sqrt x \\;\\Rightarrow\\; x = u^2 \\;\\Rightarrow\\; dx = 2u\\,du", explanation: "Square to express \\(x\\) in \\(u\\), then differentiate. The \\(2u\\) factor in \\(dx\\) is essential — without it the substitution is incomplete." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{1 + \\sqrt x}\\,dx \\;=\\; \\displaystyle\\int \\displaystyle\\frac{1}{1 + u}\\cdot 2u\\,du \\;=\\; \\displaystyle\\int \\displaystyle\\frac{2u}{1 + u}\\,du", explanation: "Direct replacement: \\(\\sqrt x \\to u\\) and \\(dx \\to 2u\\,du\\)." }, { stepNumber: 5, description: "Polynomial-divide to split into integrable pieces.", workingLatex: "\\displaystyle\\frac{2u}{1 + u} \\;=\\; \\displaystyle\\frac{2(u + 1) - 2}{1 + u} \\;=\\; 2 - \\displaystyle\\frac{2}{1 + u}", explanation: "Long division (or the algebraic split \\(2u = 2(u+1) - 2\\)) reduces the improper rational expression to a constant plus a basic \\(1/(1+u)\\) term." }, { stepNumber: 6, description: "Integrate term by term.", workingLatex: "\\displaystyle\\int \\!\\left(2 - \\displaystyle\\frac{2}{1 + u}\\right) du \\;=\\; 2u - 2\\ln|1 + u| + C", explanation: "Constant integrates to \\(2u\\); \\(\\displaystyle\\int\\!\\tfrac{1}{1+u}du = \\ln|1+u|\\) is the standard log antiderivative." }, { stepNumber: 7, description: "Back-substitute \\(u = \\sqrt x\\).", workingLatex: "= 2\\sqrt x - 2\\ln\\!\\left|1 + \\sqrt x\\right| + C", explanation: "Replace \\(u\\) with \\(\\sqrt x\\) everywhere to express the answer in terms of the original variable." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[2\\sqrt x - 2\\ln(1 + \\sqrt x)\\right] = \\displaystyle\\frac{1}{\\sqrt x} - \\displaystyle\\frac{2}{1 + \\sqrt x}\\cdot\\displaystyle\\frac{1}{2\\sqrt x} = \\displaystyle\\frac{1}{\\sqrt x} - \\displaystyle\\frac{1}{\\sqrt x(1 + \\sqrt x)} = \\displaystyle\\frac{(1 + \\sqrt x) - 1}{\\sqrt x(1 + \\sqrt x)} = \\displaystyle\\frac{1}{1 + \\sqrt x} \\;\\checkmark", explanation: "After combining over a common denominator, the derivative collapses back to the original integrand." } ], finalAnswer: "\\(2\\sqrt x - 2\\ln\\left|1 + \\sqrt x\\right| + C\\)." } },
  { id: "y2in5-005", topicRef: "y2in5", topicTitle: "Integration by Substitution 05", difficulty: "Challenge", questionText: "Use \\(u = \\sqrt{x + 1}\\) to find \\( \\displaystyle\\int x\\sqrt{x + 1}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "x = h(u) \\;\\Rightarrow\\; dx = h'(u)\\,du", explanation: "Invert the substitution so that \\(x\\) and \\(dx\\) can both be expressed in terms of \\(u\\). Needed whenever \\(x\\) appears outside the composite as a loose factor." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\text{The radical } \\sqrt{x+1} \\text{ is the obstacle; setting } u = \\sqrt{x+1} \\text{ rationalises it.}", explanation: "Once \\(u = \\sqrt{x+1}\\), the radical disappears, and the outside factor \\(x\\) can be rewritten via \\(x = u^2 - 1\\)." }, { stepNumber: 3, description: "Invert and compute \\(dx\\).", workingLatex: "u = \\sqrt{x + 1} \\;\\Rightarrow\\; x = u^2 - 1 \\;\\Rightarrow\\; dx = 2u\\,du", explanation: "Square both sides, solve for \\(x\\), then differentiate." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int x\\sqrt{x + 1}\\,dx \\;=\\; \\displaystyle\\int (u^2 - 1)\\,u\\,(2u\\,du) \\;=\\; \\displaystyle\\int 2u^2(u^2 - 1)\\,du", explanation: "Substitute \\(x = u^2 - 1\\), \\(\\sqrt{x+1} = u\\) and \\(dx = 2u\\,du\\). Group the two \\(u\\) factors." }, { stepNumber: 5, description: "Expand to a polynomial in \\(u\\).", workingLatex: "= \\displaystyle\\int (2u^4 - 2u^2)\\,du", explanation: "Distribute \\(2u^2\\) into the bracket. Polynomial integrand — straight power rule from here." }, { stepNumber: 6, description: "Integrate term by term.", workingLatex: "\\displaystyle\\int (2u^4 - 2u^2)\\,du \\;=\\; \\displaystyle\\frac{2u^5}{5} - \\displaystyle\\frac{2u^3}{3} + C", explanation: "Power rule with \\(n = 4\\) and \\(n = 2\\)." }, { stepNumber: 7, description: "Back-substitute \\(u = \\sqrt{x + 1} = (x+1)^{1/2}\\).", workingLatex: "= \\displaystyle\\frac{2(x + 1)^{\\frac{5}{2}}}{5} - \\displaystyle\\frac{2(x + 1)^{\\frac{3}{2}}}{3} + C", explanation: "Each \\(u^k\\) becomes \\((x+1)^{k/2}\\). The answer is back in terms of \\(x\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{2(x+1)^{5/2}}{5} - \\displaystyle\\frac{2(x+1)^{3/2}}{3}\\right] = (x+1)^{3/2} - (x+1)^{1/2} = (x+1)^{1/2}\\!\\left[(x+1) - 1\\right] = x\\sqrt{x+1} \\;\\checkmark", explanation: "Differentiating recovers the integrand after factoring out \\((x+1)^{1/2}\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{2(x + 1)^{\\frac{5}{2}}}{5} - \\displaystyle\\frac{2(x + 1)^{\\frac{3}{2}}}{3} + C\\)." } },
  { id: "y2in5-006", topicRef: "y2in5", topicTitle: "Integration by Substitution 06", difficulty: "Standard", questionText: "Use \\(u = x - 1\\) to find \\( \\displaystyle\\int x\\sqrt{x - 1}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx;\\; x \\text{ must also be re-expressed when it appears alone.}", explanation: "A linear shift \\(u = x - 1\\) is easy to invert: \\(x = u + 1\\). We then replace every appearance of \\(x\\)." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\sqrt{x - 1} \\text{ is the awkward piece; } u = x - 1 \\text{ flattens it to } u^{1/2}.", explanation: "After substitution, the integrand becomes a polynomial in fractional powers of \\(u\\)." }, { stepNumber: 3, description: "Invert and compute \\(dx\\).", workingLatex: "u = x - 1 \\;\\Rightarrow\\; x = u + 1,\\quad du = dx", explanation: "Trivial differential: \\(dx = du\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int x\\sqrt{x - 1}\\,dx \\;=\\; \\displaystyle\\int (u + 1)\\,u^{\\frac{1}{2}}\\,du \\;=\\; \\displaystyle\\int \\left(u^{\\frac{3}{2}} + u^{\\frac{1}{2}}\\right)\\,du", explanation: "Substitute \\(x = u + 1\\), \\(\\sqrt{x-1} = u^{1/2}\\), then distribute the bracket." }, { stepNumber: 5, description: "Integrate term by term.", workingLatex: "= \\displaystyle\\frac{u^{\\frac{5}{2}}}{\\frac{5}{2}} + \\displaystyle\\frac{u^{\\frac{3}{2}}}{\\frac{3}{2}} + C \\;=\\; \\displaystyle\\frac{2u^{\\frac{5}{2}}}{5} + \\displaystyle\\frac{2u^{\\frac{3}{2}}}{3} + C", explanation: "Power rule on each fractional-power term." }, { stepNumber: 6, description: "Back-substitute \\(u = x - 1\\).", workingLatex: "= \\displaystyle\\frac{2(x - 1)^{\\frac{5}{2}}}{5} + \\displaystyle\\frac{2(x - 1)^{\\frac{3}{2}}}{3} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{2(x-1)^{5/2}}{5} + \\displaystyle\\frac{2(x-1)^{3/2}}{3}\\right] = (x-1)^{3/2} + (x-1)^{1/2} = (x-1)^{1/2}\\!\\left[(x-1)+1\\right] = x\\sqrt{x-1} \\;\\checkmark", explanation: "Factor out \\((x-1)^{1/2}\\); the bracket simplifies to \\(x\\), giving the original integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{2(x - 1)^{\\frac{5}{2}}}{5} + \\displaystyle\\frac{2(x - 1)^{\\frac{3}{2}}}{3} + C\\)." } },
  { id: "y2in5-007", topicRef: "y2in5", topicTitle: "Integration by Substitution 07", difficulty: "Standard", questionText: "Use \\(u = x^2\\) to find \\( \\displaystyle\\int x e^{x^2}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule. We need a composite \\(f(g(x))\\) and its inner derivative \\(g'(x)\\) (up to a constant) sitting in the integrand." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "x\\,e^{x^2}: \\text{ composite } e^{x^2} \\text{ with inner } g(x) = x^2,\\; g'(x) = 2x.", explanation: "The exponent contains \\(x^2\\) and outside sits an \\(x\\) — exactly half of \\(g'(x) = 2x\\). Textbook u-sub setup." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = x^2 \\;\\Rightarrow\\; du = 2x\\,dx \\;\\Rightarrow\\; x\\,dx = \\displaystyle\\frac{1}{2}\\,du", explanation: "Differentiate \\(u\\) and rearrange so the bundle \\(x\\,dx\\) appearing in the integrand can be replaced directly." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int x e^{x^2}\\,dx \\;=\\; \\displaystyle\\int e^u \\cdot \\displaystyle\\frac{1}{2}\\,du \\;=\\; \\displaystyle\\frac{1}{2}\\displaystyle\\int e^u\\,du", explanation: "\\(e^{x^2} \\to e^u\\) and \\(x\\,dx \\to \\tfrac{1}{2}du\\). Pull the constant out." }, { stepNumber: 5, description: "Integrate using the exponential rule.", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int e^u\\,du \\;=\\; \\displaystyle\\frac{1}{2}e^u + C", explanation: "Standard antiderivative \\(\\displaystyle\\int e^u\\,du = e^u + C\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = x^2\\).", workingLatex: "= \\displaystyle\\frac{e^{x^2}}{2} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{e^{x^2}}{2}\\right] = \\displaystyle\\frac{e^{x^2}\\cdot 2x}{2} = x\\,e^{x^2} \\;\\checkmark", explanation: "Chain rule on \\(e^{x^2}\\) recovers the integrand exactly." } ], finalAnswer: "\\(\\displaystyle\\frac{e^{x^2}}{2} + C\\)." } },
  { id: "y2in5-008", topicRef: "y2in5", topicTitle: "Integration by Substitution 08", difficulty: "Standard", questionText: "Use \\(u = \\ln x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{\\ln x}{x}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Look for a composite multiplied by its inner derivative." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\displaystyle\\frac{\\ln x}{x} = \\ln x \\cdot \\displaystyle\\frac{1}{x},\\; \\text{ inner } g(x) = \\ln x \\text{ with } g'(x) = \\displaystyle\\frac{1}{x}.", explanation: "The integrand is exactly \\(g(x)\\cdot g'(x)\\) — the inner function appears alongside its own derivative." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\ln x \\;\\Rightarrow\\; du = \\displaystyle\\frac{1}{x}\\,dx", explanation: "Differentiate the logarithm; the \\(\\tfrac{1}{x}\\,dx\\) bundle that appears in the integrand becomes simply \\(du\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\ln x}{x}\\,dx \\;=\\; \\displaystyle\\int u\\,du", explanation: "\\(\\ln x \\to u\\) and \\(\\tfrac{1}{x}dx \\to du\\)." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "\\displaystyle\\int u\\,du \\;=\\; \\displaystyle\\frac{u^2}{2} + C", explanation: "Power rule with \\(n = 1\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = \\ln x\\).", workingLatex: "= \\displaystyle\\frac{(\\ln x)^2}{2} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(\\ln x)^2}{2}\\right] = \\displaystyle\\frac{2\\ln x}{2}\\cdot\\displaystyle\\frac{1}{x} = \\displaystyle\\frac{\\ln x}{x} \\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(\\ln x)^2}{2} + C\\)." } },
  { id: "y2in5-009", topicRef: "y2in5", topicTitle: "Integration by Substitution 09", difficulty: "Standard", questionText: "Use \\(u = 3 - x^2\\) to find \\( \\displaystyle\\int x(3 - x^2)^5\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule template — composite plus inner derivative collapses to a one-variable integral." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "(3 - x^2)^5 \\cdot x: \\text{ inner } g(x) = 3 - x^2,\\; g'(x) = -2x.", explanation: "The bracket is a composite and the outside factor \\(x\\) is \\(-\\tfrac{1}{2}\\) of \\(g'(x)\\). The negative sign will appear in the constant." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 3 - x^2 \\;\\Rightarrow\\; du = -2x\\,dx \\;\\Rightarrow\\; x\\,dx = -\\displaystyle\\frac{1}{2}\\,du", explanation: "Track the negative sign carefully — it stays attached to the \\(\\tfrac{1}{2}\\) outside the integral." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int x(3 - x^2)^5\\,dx \\;=\\; \\displaystyle\\int u^5 \\cdot \\!\\left(-\\displaystyle\\frac{1}{2}\\right)du \\;=\\; -\\displaystyle\\frac{1}{2}\\displaystyle\\int u^5\\,du", explanation: "Every \\(x\\) gone; the negative half pulls outside." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "-\\displaystyle\\frac{1}{2}\\displaystyle\\int u^5\\,du \\;=\\; -\\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{u^6}{6} + C \\;=\\; -\\displaystyle\\frac{u^6}{12} + C", explanation: "Power rule with \\(n = 5\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = 3 - x^2\\).", workingLatex: "= -\\displaystyle\\frac{(3 - x^2)^6}{12} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{(3 - x^2)^6}{12}\\right] = -\\displaystyle\\frac{6(3-x^2)^5\\cdot(-2x)}{12} = x(3 - x^2)^5 \\;\\checkmark", explanation: "The two negatives cancel; chain rule recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{(3 - x^2)^6}{12} + C\\)." } },
  { id: "y2in5-010", topicRef: "y2in5", topicTitle: "Integration by Substitution 10", difficulty: "Foundation", questionText: "Use \\(u = 2x + 3\\) to find \\( \\displaystyle\\int \\left(2x + 3\\right)^{10}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Substitute the inner function with \\(u\\) and rewrite the differential element." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "(2x + 3)^{10}: \\text{ inner } 2x + 3 \\text{ with derivative } 2 \\text{ — a constant.}", explanation: "Because \\(g'(x) = 2\\) is a constant, it factors out cleanly. A linear inside-and-power-outside is the simplest u-sub setup." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 2x + 3 \\;\\Rightarrow\\; du = 2\\,dx \\;\\Rightarrow\\; dx = \\displaystyle\\frac{du}{2}", explanation: "Solve for \\(dx\\) so it can be substituted in." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int (2x + 3)^{10}\\,dx \\;=\\; \\displaystyle\\int u^{10}\\cdot\\displaystyle\\frac{du}{2} \\;=\\; \\displaystyle\\frac{1}{2}\\displaystyle\\int u^{10}\\,du", explanation: "Direct replacement and constant pulled out." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int u^{10}\\,du \\;=\\; \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{u^{11}}{11} + C \\;=\\; \\displaystyle\\frac{u^{11}}{22} + C", explanation: "Power rule with \\(n = 10\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = 2x + 3\\).", workingLatex: "= \\displaystyle\\frac{(2x + 3)^{11}}{22} + C", explanation: "Restore the original variable." } ], finalAnswer: "\\(\\displaystyle\\frac{(2x + 3)^{11}}{22} + C\\)." } },
  // ── Trig substitutions ────
  { id: "y2in5-011", topicRef: "y2in5", topicTitle: "Integration by Substitution 11", difficulty: "Standard", questionText: "Use \\(u = \\sin x\\) to find \\( \\displaystyle\\int \\sin^2 x\\cos x\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule. For trig integrands, look for a trig function and its derivative (e.g.\\ \\(\\sin x\\) and \\(\\cos x\\))." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\sin^2 x\\cos x = (\\sin x)^2 \\cdot \\cos x \\text{ — power of } \\sin x \\text{ multiplied by its derivative.}", explanation: "Since \\(\\displaystyle\\frac{d}{dx}\\sin x = \\cos x\\), the integrand is exactly \\(u^2\\,du\\) once we pick \\(u = \\sin x\\)." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\sin x \\;\\Rightarrow\\; du = \\cos x\\,dx", explanation: "Differentiate the inner trig function." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\sin^2 x\\cos x\\,dx \\;=\\; \\displaystyle\\int u^2\\,du", explanation: "\\((\\sin x)^2 \\to u^2\\); the \\(\\cos x\\,dx\\) bundle becomes \\(du\\)." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "\\displaystyle\\int u^2\\,du \\;=\\; \\displaystyle\\frac{u^3}{3} + C", explanation: "Power rule with \\(n = 2\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = \\sin x\\).", workingLatex: "= \\displaystyle\\frac{\\sin^3 x}{3} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{\\sin^3 x}{3}\\right] = \\displaystyle\\frac{3\\sin^2 x \\cos x}{3} = \\sin^2 x\\cos x \\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{\\sin^3 x}{3} + C\\)." } },
  { id: "y2in5-012", topicRef: "y2in5", topicTitle: "Integration by Substitution 12", difficulty: "Challenge", questionText: "Use \\(u = \\cos x\\) to find \\( \\displaystyle\\int \\sin^3 x\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Substitution again — but first we need to manufacture a \\(\\sin x\\,dx\\) factor by trig manipulation." }, { stepNumber: 2, description: "Why u-substitution fits here — split off one \\(\\sin x\\).", workingLatex: "\\sin^3 x = \\sin^2 x\\cdot\\sin x = (1 - \\cos^2 x)\\sin x", explanation: "Pythagorean identity \\(\\sin^2 x = 1 - \\cos^2 x\\). This rewrite isolates a single \\(\\sin x\\) factor — exactly the derivative of \\(\\cos x\\) (up to sign)." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\cos x \\;\\Rightarrow\\; du = -\\sin x\\,dx \\;\\Rightarrow\\; \\sin x\\,dx = -du", explanation: "Differentiate \\(\\cos x\\); the negative sign is part of the derivative and must travel into the substitution." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\sin^3 x\\,dx \\;=\\; \\displaystyle\\int (1 - \\cos^2 x)\\sin x\\,dx \\;=\\; \\displaystyle\\int (1 - u^2)(-du) \\;=\\; \\displaystyle\\int (u^2 - 1)\\,du", explanation: "\\(\\cos x \\to u\\) and \\(\\sin x\\,dx \\to -du\\); the negative absorbs into the bracket, flipping the sign." }, { stepNumber: 5, description: "Integrate term by term.", workingLatex: "\\displaystyle\\int (u^2 - 1)\\,du \\;=\\; \\displaystyle\\frac{u^3}{3} - u + C", explanation: "Power rule on each term." }, { stepNumber: 6, description: "Back-substitute \\(u = \\cos x\\).", workingLatex: "= \\displaystyle\\frac{\\cos^3 x}{3} - \\cos x + C \\;=\\; -\\cos x + \\displaystyle\\frac{\\cos^3 x}{3} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\cos x + \\displaystyle\\frac{\\cos^3 x}{3}\\right] = \\sin x + \\cos^2 x \\cdot (-\\sin x) = \\sin x(1 - \\cos^2 x) = \\sin x \\cdot \\sin^2 x = \\sin^3 x \\;\\checkmark", explanation: "Pythagorean identity at the last step recovers the integrand." } ], finalAnswer: "\\(-\\cos x + \\displaystyle\\frac{\\cos^3 x}{3} + C\\)." } },
  { id: "y2in5-013", topicRef: "y2in5", topicTitle: "Integration by Substitution 13", difficulty: "Standard", questionText: "Use \\(u = \\tan x\\) to find \\( \\displaystyle\\int \\sec^2 x\\tan^3 x\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule. Recall \\(\\displaystyle\\frac{d}{dx}\\tan x = \\sec^2 x\\) — the appearance of \\(\\sec^2 x\\) in the integrand is the cue." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\tan^3 x \\cdot \\sec^2 x = (\\tan x)^3 \\cdot \\!\\left[\\displaystyle\\frac{d}{dx}\\tan x\\right]", explanation: "A power of \\(\\tan x\\) sitting alongside its derivative — picture-perfect u-sub form." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\tan x \\;\\Rightarrow\\; du = \\sec^2 x\\,dx", explanation: "Differentiate \\(\\tan x\\). The bundle \\(\\sec^2 x\\,dx\\) becomes \\(du\\) exactly." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\sec^2 x\\tan^3 x\\,dx \\;=\\; \\displaystyle\\int u^3\\,du", explanation: "\\((\\tan x)^3 \\to u^3\\); \\(\\sec^2 x\\,dx \\to du\\)." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "\\displaystyle\\int u^3\\,du \\;=\\; \\displaystyle\\frac{u^4}{4} + C", explanation: "Power rule with \\(n = 3\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = \\tan x\\).", workingLatex: "= \\displaystyle\\frac{\\tan^4 x}{4} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{\\tan^4 x}{4}\\right] = \\displaystyle\\frac{4\\tan^3 x\\cdot\\sec^2 x}{4} = \\sec^2 x\\tan^3 x \\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{\\tan^4 x}{4} + C\\)." } },
  { id: "y2in5-014", topicRef: "y2in5", topicTitle: "Integration by Substitution 14", difficulty: "Challenge", questionText: "Use \\(u = \\sin x\\) to find \\( \\displaystyle\\int \\cos^3 x\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Substitution preceded by a Pythagorean manipulation — we need a \\(\\cos x\\,dx\\) factor." }, { stepNumber: 2, description: "Why u-substitution fits — split off one \\(\\cos x\\).", workingLatex: "\\cos^3 x = \\cos^2 x \\cdot \\cos x = (1 - \\sin^2 x)\\cos x", explanation: "Pythagorean identity \\(\\cos^2 x = 1 - \\sin^2 x\\) isolates a single \\(\\cos x\\) — exactly the derivative of \\(\\sin x\\)." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\sin x \\;\\Rightarrow\\; du = \\cos x\\,dx", explanation: "Differentiate; the bundle \\(\\cos x\\,dx\\) becomes \\(du\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\cos^3 x\\,dx \\;=\\; \\displaystyle\\int (1 - \\sin^2 x)\\cos x\\,dx \\;=\\; \\displaystyle\\int (1 - u^2)\\,du", explanation: "Direct substitution after the trig split." }, { stepNumber: 5, description: "Integrate term by term.", workingLatex: "\\displaystyle\\int (1 - u^2)\\,du \\;=\\; u - \\displaystyle\\frac{u^3}{3} + C", explanation: "Power rule on each term." }, { stepNumber: 6, description: "Back-substitute \\(u = \\sin x\\).", workingLatex: "= \\sin x - \\displaystyle\\frac{\\sin^3 x}{3} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\sin x - \\displaystyle\\frac{\\sin^3 x}{3}\\right] = \\cos x - \\sin^2 x\\cos x = \\cos x(1 - \\sin^2 x) = \\cos x \\cdot \\cos^2 x = \\cos^3 x \\;\\checkmark", explanation: "Pythagorean identity confirms the integrand is recovered." } ], finalAnswer: "\\(\\sin x - \\displaystyle\\frac{\\sin^3 x}{3} + C\\)." } },
  { id: "y2in5-015", topicRef: "y2in5", topicTitle: "Integration by Substitution 15", difficulty: "Standard", questionText: "Use \\(u = 1 + \\cos x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{\\sin x}{1 + \\cos x}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule. Here we also have a \\(f'/f\\) flavour — the numerator is (up to a sign) the derivative of the denominator." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\displaystyle\\frac{d}{dx}(1 + \\cos x) = -\\sin x \\text{ — numerator is } -\\,g'(x).", explanation: "Setting \\(u = 1 + \\cos x\\), the integrand becomes \\(\\tfrac{1}{u}\\) times \\(du\\) (with a sign flip)." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 1 + \\cos x \\;\\Rightarrow\\; du = -\\sin x\\,dx \\;\\Rightarrow\\; \\sin x\\,dx = -du", explanation: "Track the negative carefully." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\sin x}{1 + \\cos x}\\,dx \\;=\\; \\displaystyle\\int \\displaystyle\\frac{-du}{u} \\;=\\; -\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "\\(1 + \\cos x \\to u\\), \\(\\sin x\\,dx \\to -du\\). Pull the minus out." }, { stepNumber: 5, description: "Integrate using the log rule.", workingLatex: "-\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du \\;=\\; -\\ln|u| + C", explanation: "Standard antiderivative \\(\\displaystyle\\int \\tfrac{1}{u}du = \\ln|u| + C\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = 1 + \\cos x\\).", workingLatex: "= -\\ln\\!\\left|1 + \\cos x\\right| + C", explanation: "Restore the original variable. Modulus stays because \\(1 + \\cos x = 0\\) at \\(x = \\pi + 2k\\pi\\) — though never negative, it can be zero." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\ln|1 + \\cos x|\\right] = -\\displaystyle\\frac{-\\sin x}{1 + \\cos x} = \\displaystyle\\frac{\\sin x}{1 + \\cos x} \\;\\checkmark", explanation: "Two negatives cancel; the integrand is recovered." } ], finalAnswer: "\\(-\\ln\\left|1 + \\cos x\\right| + C\\)." } },
  // ── Exp/log ────
  { id: "y2in5-016", topicRef: "y2in5", topicTitle: "Integration by Substitution 16", difficulty: "Standard", questionText: "Use \\(u = e^x + 1\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{e^x}{\\left(e^x + 1\\right)^2}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule. The denominator is a composite; the numerator is its derivative." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\displaystyle\\frac{d}{dx}(e^x + 1) = e^x \\text{ — numerator equals } g'(x).", explanation: "Setting \\(u = e^x + 1\\), the integrand collapses to \\(u^{-2}\\,du\\)." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = e^x + 1 \\;\\Rightarrow\\; du = e^x\\,dx", explanation: "Differentiate. The \\(e^x\\,dx\\) bundle in the integrand becomes \\(du\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{e^x}{(e^x + 1)^2}\\,dx \\;=\\; \\displaystyle\\int \\displaystyle\\frac{du}{u^2} \\;=\\; \\displaystyle\\int u^{-2}\\,du", explanation: "Express the denominator as \\(u^2\\) and the numerator-with-\\(dx\\) as \\(du\\)." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "\\displaystyle\\int u^{-2}\\,du \\;=\\; \\displaystyle\\frac{u^{-1}}{-1} + C \\;=\\; -\\displaystyle\\frac{1}{u} + C", explanation: "Power rule with \\(n = -2\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = e^x + 1\\).", workingLatex: "= -\\displaystyle\\frac{1}{e^x + 1} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{1}{e^x + 1}\\right] = \\displaystyle\\frac{e^x}{(e^x + 1)^2} \\;\\checkmark", explanation: "Quotient/chain rule recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{1}{e^x + 1} + C\\)." } },
  { id: "y2in5-017", topicRef: "y2in5", topicTitle: "Integration by Substitution 17", difficulty: "Challenge", questionText: "Use \\(u = e^x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{e^{2x}}{e^x + 1}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule, used here to rationalise an exponential expression into an algebraic one in \\(u\\)." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "e^{2x} = e^x \\cdot e^x \\text{ — one } e^x \\text{ pairs with } dx, \\text{ the other becomes } u.", explanation: "Splitting \\(e^{2x}\\) provides the \\(e^x\\,dx\\) bundle needed for \\(du\\), and leaves an algebraic factor of \\(e^x = u\\) inside." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = e^x \\;\\Rightarrow\\; du = e^x\\,dx", explanation: "Differentiate the exponential; the bundle \\(e^x\\,dx\\) becomes \\(du\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{e^{2x}}{e^x + 1}\\,dx \\;=\\; \\displaystyle\\int \\displaystyle\\frac{e^x \\cdot e^x}{e^x + 1}\\,dx \\;=\\; \\displaystyle\\int \\displaystyle\\frac{u}{u + 1}\\,du", explanation: "Direct substitution after the split." }, { stepNumber: 5, description: "Polynomial-divide to expose integrable pieces.", workingLatex: "\\displaystyle\\frac{u}{u + 1} \\;=\\; \\displaystyle\\frac{(u + 1) - 1}{u + 1} \\;=\\; 1 - \\displaystyle\\frac{1}{u + 1}", explanation: "Rewrite as a constant plus a \\(1/(u+1)\\) term — both standard antiderivatives." }, { stepNumber: 6, description: "Integrate term by term.", workingLatex: "\\displaystyle\\int \\!\\left(1 - \\displaystyle\\frac{1}{u + 1}\\right)du \\;=\\; u - \\ln|u + 1| + C", explanation: "Constant integrates to \\(u\\); \\(\\displaystyle\\int \\tfrac{1}{u+1}du = \\ln|u+1|\\)." }, { stepNumber: 7, description: "Back-substitute \\(u = e^x\\).", workingLatex: "= e^x - \\ln(e^x + 1) + C", explanation: "Since \\(e^x + 1 > 0\\) for all real \\(x\\), the modulus bars are redundant and can be dropped." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[e^x - \\ln(e^x + 1)\\right] = e^x - \\displaystyle\\frac{e^x}{e^x + 1} = \\displaystyle\\frac{e^x(e^x + 1) - e^x}{e^x + 1} = \\displaystyle\\frac{e^{2x}}{e^x + 1} \\;\\checkmark", explanation: "After combining over a common denominator, the integrand is recovered." } ], finalAnswer: "\\(e^x - \\ln(e^x + 1) + C\\)." } },
  { id: "y2in5-018", topicRef: "y2in5", topicTitle: "Integration by Substitution 18", difficulty: "Standard", questionText: "Use \\(u = \\ln x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{1}{x(\\ln x)^2}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\displaystyle\\frac{1}{x(\\ln x)^2} = (\\ln x)^{-2}\\cdot\\displaystyle\\frac{1}{x}", explanation: "Power of \\(\\ln x\\) multiplied by the derivative of \\(\\ln x\\) — perfect u-sub form." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\ln x \\;\\Rightarrow\\; du = \\displaystyle\\frac{1}{x}\\,dx", explanation: "Differentiate the logarithm; the bundle \\(\\tfrac{1}{x}\\,dx\\) becomes \\(du\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{x(\\ln x)^2}\\,dx \\;=\\; \\displaystyle\\int u^{-2}\\,du", explanation: "Direct replacement." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "\\displaystyle\\int u^{-2}\\,du \\;=\\; -u^{-1} + C \\;=\\; -\\displaystyle\\frac{1}{u} + C", explanation: "Power rule with \\(n = -2\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = \\ln x\\).", workingLatex: "= -\\displaystyle\\frac{1}{\\ln x} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{1}{\\ln x}\\right] = \\displaystyle\\frac{1}{(\\ln x)^2}\\cdot\\displaystyle\\frac{1}{x} = \\displaystyle\\frac{1}{x(\\ln x)^2} \\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{1}{\\ln x} + C\\)." } },
  { id: "y2in5-019", topicRef: "y2in5", topicTitle: "Integration by Substitution 19", difficulty: "Standard", questionText: "Use \\(u = 1 - x^2\\) to find \\( \\displaystyle\\int x\\sqrt{1 - x^2}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\sqrt{1 - x^2}\\cdot x: \\text{ inner } 1 - x^2 \\text{ with derivative } -2x.", explanation: "The outside \\(x\\) is \\(-\\tfrac{1}{2}\\) of \\(g'(x)\\) — clean u-sub up to a constant." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 1 - x^2 \\;\\Rightarrow\\; du = -2x\\,dx \\;\\Rightarrow\\; x\\,dx = -\\displaystyle\\frac{1}{2}\\,du", explanation: "Track the negative sign." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int x\\sqrt{1 - x^2}\\,dx \\;=\\; \\displaystyle\\int u^{\\frac{1}{2}}\\!\\left(-\\displaystyle\\frac{1}{2}\\right)du \\;=\\; -\\displaystyle\\frac{1}{2}\\displaystyle\\int u^{\\frac{1}{2}}\\,du", explanation: "Direct substitution; constant pulls out." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "-\\displaystyle\\frac{1}{2}\\displaystyle\\int u^{\\frac{1}{2}}\\,du \\;=\\; -\\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{u^{\\frac{3}{2}}}{\\frac{3}{2}} + C \\;=\\; -\\displaystyle\\frac{u^{\\frac{3}{2}}}{3} + C", explanation: "Power rule with \\(n = \\tfrac{1}{2}\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = 1 - x^2\\).", workingLatex: "= -\\displaystyle\\frac{(1 - x^2)^{\\frac{3}{2}}}{3} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{(1 - x^2)^{3/2}}{3}\\right] = -\\displaystyle\\frac{\\frac{3}{2}(1 - x^2)^{1/2}\\cdot(-2x)}{3} = x\\sqrt{1 - x^2} \\;\\checkmark", explanation: "Negatives cancel; integrand recovered." } ], finalAnswer: "\\(-\\displaystyle\\frac{(1 - x^2)^{\\frac{3}{2}}}{3} + C\\)." } },
  { id: "y2in5-020", topicRef: "y2in5", topicTitle: "Integration by Substitution 20", difficulty: "Standard", questionText: "Use \\(u = 1 + x^2\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{x}{\\left(1 + x^2\\right)^3}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Reverse chain rule." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\displaystyle\\frac{x}{(1 + x^2)^3}: \\text{ inner } 1 + x^2 \\text{ with derivative } 2x.", explanation: "Outside factor \\(x\\) is half of \\(g'(x)\\) — perfect setup for u-sub." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 1 + x^2 \\;\\Rightarrow\\; du = 2x\\,dx \\;\\Rightarrow\\; x\\,dx = \\displaystyle\\frac{1}{2}\\,du", explanation: "Rearrange so the bundle \\(x\\,dx\\) can be swapped wholesale." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{(1 + x^2)^3}\\,dx \\;=\\; \\displaystyle\\int \\displaystyle\\frac{1}{u^3}\\cdot\\displaystyle\\frac{1}{2}\\,du \\;=\\; \\displaystyle\\frac{1}{2}\\displaystyle\\int u^{-3}\\,du", explanation: "Direct replacement." }, { stepNumber: 5, description: "Integrate using the power rule.", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int u^{-3}\\,du \\;=\\; \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{u^{-2}}{-2} + C \\;=\\; -\\displaystyle\\frac{1}{4u^2} + C", explanation: "Power rule with \\(n = -3\\)." }, { stepNumber: 6, description: "Back-substitute \\(u = 1 + x^2\\).", workingLatex: "= -\\displaystyle\\frac{1}{4(1 + x^2)^2} + C", explanation: "Restore the original variable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{1}{4(1 + x^2)^2}\\right] = -\\displaystyle\\frac{-2(1 + x^2)^{-3}\\cdot 2x}{4} = \\displaystyle\\frac{x}{(1 + x^2)^3} \\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{1}{4(1 + x^2)^2} + C\\)." } },
  // ── Definite integrals with substitution ────
  { id: "y2in5-021", topicRef: "y2in5", topicTitle: "Integration by Substitution 21", difficulty: "Standard", questionText: "Use \\(u = x^2 + 1\\) to evaluate \\( \\displaystyle\\int_0^1 x\\sqrt{x^2 + 1}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template (definite version).", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx,\\quad \\displaystyle\\int_a^b f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int_{g(a)}^{g(b)} f(u)\\,du", explanation: "For definite integrals, convert the limits as well — then no back-substitution is needed." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "x\\sqrt{x^2 + 1}: \\text{ inner } x^2 + 1 \\text{ with derivative } 2x.", explanation: "Outside factor \\(x\\) is half of \\(g'(x)\\) — classic u-sub." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = x^2 + 1 \\;\\Rightarrow\\; du = 2x\\,dx \\;\\Rightarrow\\; x\\,dx = \\displaystyle\\frac{1}{2}\\,du", explanation: "Bundle the outside \\(x\\,dx\\) to be replaced wholesale." }, { stepNumber: 4, description: "Convert the limits.", workingLatex: "x = 0 \\;\\Rightarrow\\; u = 1;\\quad x = 1 \\;\\Rightarrow\\; u = 2", explanation: "Plug the original \\(x\\)-limits into \\(u = x^2 + 1\\) to get the new \\(u\\)-limits." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int_0^1 x\\sqrt{x^2 + 1}\\,dx \\;=\\; \\displaystyle\\frac{1}{2}\\displaystyle\\int_1^2 u^{\\frac{1}{2}}\\,du", explanation: "Substitute, pull the \\(\\tfrac{1}{2}\\) out, and use the new limits." }, { stepNumber: 6, description: "Integrate using the power rule.", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int_1^2 u^{\\frac{1}{2}}\\,du \\;=\\; \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{2}{3}\\!\\left[u^{\\frac{3}{2}}\\right]_1^2 \\;=\\; \\displaystyle\\frac{1}{3}\\!\\left[u^{\\frac{3}{2}}\\right]_1^2", explanation: "Power rule with \\(n = \\tfrac{1}{2}\\); leave the antiderivative in evaluation form." }, { stepNumber: 7, description: "Evaluate at the limits.", workingLatex: "= \\displaystyle\\frac{1}{3}\\!\\left(2^{\\frac{3}{2}} - 1^{\\frac{3}{2}}\\right) \\;=\\; \\displaystyle\\frac{1}{3}\\!\\left(2\\sqrt 2 - 1\\right) \\;=\\; \\displaystyle\\frac{2\\sqrt 2 - 1}{3}", explanation: "Apply the upper and lower limits. \\(2^{3/2} = 2\\sqrt 2\\) and \\(1^{3/2} = 1\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{2\\sqrt 2 - 1}{3}\\)." } },
  { id: "y2in5-022", topicRef: "y2in5", topicTitle: "Integration by Substitution 22", difficulty: "Standard", questionText: "Use \\(u = \\sin x\\) to evaluate \\( \\displaystyle\\int_0^{\\pi/2} \\sin^2 x\\cos x\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template (definite version).", workingLatex: "\\displaystyle\\int_a^b f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int_{g(a)}^{g(b)} f(u)\\,du", explanation: "Convert the limits using \\(u = g(x)\\); no back-substitution needed." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\sin^2 x\\cos x = (\\sin x)^2\\cdot\\!\\left[\\displaystyle\\frac{d}{dx}\\sin x\\right]", explanation: "Power of \\(\\sin x\\) multiplied by its derivative \\(\\cos x\\) — textbook u-sub." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\sin x \\;\\Rightarrow\\; du = \\cos x\\,dx", explanation: "Differentiate; the bundle \\(\\cos x\\,dx\\) becomes \\(du\\)." }, { stepNumber: 4, description: "Convert the limits.", workingLatex: "x = 0 \\;\\Rightarrow\\; u = \\sin 0 = 0;\\quad x = \\displaystyle\\frac{\\pi}{2} \\;\\Rightarrow\\; u = \\sin\\!\\displaystyle\\frac{\\pi}{2} = 1", explanation: "Plug the original limits into \\(u = \\sin x\\)." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int_0^{\\pi/2} \\sin^2 x\\cos x\\,dx \\;=\\; \\displaystyle\\int_0^1 u^2\\,du", explanation: "Direct replacement with new limits." }, { stepNumber: 6, description: "Integrate using the power rule.", workingLatex: "\\displaystyle\\int_0^1 u^2\\,du \\;=\\; \\left[\\displaystyle\\frac{u^3}{3}\\right]_0^1", explanation: "Power rule with \\(n = 2\\)." }, { stepNumber: 7, description: "Evaluate at the limits.", workingLatex: "= \\displaystyle\\frac{1^3}{3} - \\displaystyle\\frac{0^3}{3} = \\displaystyle\\frac{1}{3}", explanation: "Upper minus lower." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{3}\\)." } },
  { id: "y2in5-023", topicRef: "y2in5", topicTitle: "Integration by Substitution 23", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^1 x e^{x^2}\\,dx \\) using \\(u = x^2\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template (definite version).", workingLatex: "\\displaystyle\\int_a^b f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int_{g(a)}^{g(b)} f(u)\\,du", explanation: "Switch to the \\(u\\)-limits and integrate in \\(u\\)." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "xe^{x^2}: \\text{ inner } x^2 \\text{ with derivative } 2x.", explanation: "Outside factor \\(x\\) is half of \\(g'(x)\\)." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = x^2 \\;\\Rightarrow\\; du = 2x\\,dx \\;\\Rightarrow\\; x\\,dx = \\displaystyle\\frac{1}{2}\\,du", explanation: "Rearrange to bundle \\(x\\,dx\\)." }, { stepNumber: 4, description: "Convert the limits.", workingLatex: "x = 0 \\;\\Rightarrow\\; u = 0;\\quad x = 1 \\;\\Rightarrow\\; u = 1", explanation: "Square each \\(x\\)-limit." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int_0^1 xe^{x^2}\\,dx \\;=\\; \\displaystyle\\frac{1}{2}\\displaystyle\\int_0^1 e^u\\,du", explanation: "Direct replacement; \\(\\tfrac{1}{2}\\) pulls out." }, { stepNumber: 6, description: "Integrate using the exponential rule.", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int_0^1 e^u\\,du \\;=\\; \\displaystyle\\frac{1}{2}\\!\\left[e^u\\right]_0^1", explanation: "Standard antiderivative \\(\\displaystyle\\int e^u\\,du = e^u\\)." }, { stepNumber: 7, description: "Evaluate at the limits.", workingLatex: "= \\displaystyle\\frac{1}{2}(e^1 - e^0) = \\displaystyle\\frac{e - 1}{2}", explanation: "Use \\(e^0 = 1\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{e - 1}{2}\\)." } },
  { id: "y2in5-024", topicRef: "y2in5", topicTitle: "Integration by Substitution 24", difficulty: "Standard", questionText: "Use \\(u = x^2 + 1\\) to evaluate \\( \\displaystyle\\int_1^2 \\displaystyle\\frac{x}{x^2 + 1}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template (definite version).", workingLatex: "\\displaystyle\\int_a^b f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int_{g(a)}^{g(b)} f(u)\\,du", explanation: "Convert the limits using \\(u = g(x)\\); evaluate directly in \\(u\\)." }, { stepNumber: 2, description: "Why u-substitution fits here.", workingLatex: "\\displaystyle\\frac{x}{x^2 + 1}: \\text{ numerator is } \\tfrac{1}{2}\\,g'(x) \\text{ where } g(x) = x^2 + 1.", explanation: "Classic \\(f'/f\\) shape — antiderivative will be a logarithm." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = x^2 + 1 \\;\\Rightarrow\\; du = 2x\\,dx \\;\\Rightarrow\\; x\\,dx = \\displaystyle\\frac{1}{2}\\,du", explanation: "Bundle the \\(x\\,dx\\) factor." }, { stepNumber: 4, description: "Convert the limits.", workingLatex: "x = 1 \\;\\Rightarrow\\; u = 2;\\quad x = 2 \\;\\Rightarrow\\; u = 5", explanation: "Plug each \\(x\\)-limit into \\(u = x^2 + 1\\)." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int_1^2 \\displaystyle\\frac{x}{x^2 + 1}\\,dx \\;=\\; \\displaystyle\\frac{1}{2}\\displaystyle\\int_2^5 \\displaystyle\\frac{1}{u}\\,du", explanation: "Direct replacement; \\(\\tfrac{1}{2}\\) pulls out." }, { stepNumber: 6, description: "Integrate using the log rule.", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int_2^5 \\displaystyle\\frac{1}{u}\\,du \\;=\\; \\displaystyle\\frac{1}{2}\\!\\left[\\ln u\\right]_2^5", explanation: "Standard antiderivative \\(\\displaystyle\\int \\tfrac{1}{u}du = \\ln|u|\\); modulus dropped since \\(u > 0\\) on \\([2,5]\\)." }, { stepNumber: 7, description: "Evaluate at the limits.", workingLatex: "= \\displaystyle\\frac{1}{2}(\\ln 5 - \\ln 2) = \\displaystyle\\frac{1}{2}\\ln\\!\\displaystyle\\frac{5}{2}", explanation: "Use the log subtraction law \\(\\ln 5 - \\ln 2 = \\ln(5/2)\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln\\displaystyle\\frac{5}{2}\\)." } },
  { id: "y2in5-025", topicRef: "y2in5", topicTitle: "Integration by Substitution 25", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/4} \\sec^2 x\\tan^2 x\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x)\\;\\Rightarrow\\;du = g'(x)\\,dx\\;\\Rightarrow\\;\\displaystyle\\int f(g(x))\\,g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Standard u-substitution." }, { stepNumber: 2, description: "Identify the function-and-its-derivative pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}\\tan x = \\sec^2 x", explanation: "The integrand contains \\(\\tan^2 x\\) (a function of \\(\\tan x\\)) times its derivative \\(\\sec^2 x\\)." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\tan x \\;\\Rightarrow\\; du = \\sec^2 x\\,dx", explanation: "Pick the inner function." }, { stepNumber: 4, description: "Convert the limits.", workingLatex: "x = 0 \\Rightarrow u = \\tan 0 = 0,\\quad x = \\displaystyle\\frac{\\pi}{4} \\Rightarrow u = \\tan\\displaystyle\\frac{\\pi}{4} = 1", explanation: "Change the limits to \\(u\\)-values to avoid back-substituting." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int_0^{\\pi/4}\\sec^2 x\\tan^2 x\\,dx = \\displaystyle\\int_0^1 u^2\\,du", explanation: "The \\(\\sec^2 x\\,dx\\) bundles into \\(du\\); \\(\\tan^2 x = u^2\\)." }, { stepNumber: 6, description: "Integrate in \\(u\\) and evaluate.", workingLatex: "\\left[\\displaystyle\\frac{u^3}{3}\\right]_0^1 = \\displaystyle\\frac{1}{3} - 0 = \\displaystyle\\frac{1}{3}", explanation: "Power rule then apply the new limits." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(\\displaystyle\\frac{\\tan^3 x}{3}\\right) = \\tan^2 x\\sec^2 x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{3}\\)." } },
  { id: "y2in5-026", topicRef: "y2in5", topicTitle: "Integration by Substitution 26", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_1^4 \\sqrt{x + 5}\\,dx \\) (use \\(u = x + 5\\)).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x)\\;\\Rightarrow\\;du = g'(x)\\,dx", explanation: "Standard u-substitution." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = x + 5 \\;\\Rightarrow\\; du = dx", explanation: "Linear inner function — \\(dx\\) and \\(du\\) are interchangeable." }, { stepNumber: 3, description: "Convert the limits.", workingLatex: "x = 1 \\Rightarrow u = 6,\\quad x = 4 \\Rightarrow u = 9", explanation: "Shift each limit by \\(+5\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int_1^4 \\sqrt{x + 5}\\,dx = \\displaystyle\\int_6^9 u^{1/2}\\,du", explanation: "Direct substitution." }, { stepNumber: 5, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int_6^9 u^{1/2}\\,du = \\left[\\displaystyle\\frac{2u^{3/2}}{3}\\right]_6^9", explanation: "Power rule: \\(\\displaystyle\\int u^{1/2}\\,du = \\displaystyle\\frac{2}{3}u^{3/2}\\)." }, { stepNumber: 6, description: "Evaluate the limits.", workingLatex: "= \\displaystyle\\frac{2}{3}\\left(9^{3/2} - 6^{3/2}\\right) = \\displaystyle\\frac{2}{3}\\left(27 - 6\\sqrt 6\\right) = 18 - 4\\sqrt 6", explanation: "\\(9^{3/2} = 27\\); \\(6^{3/2} = 6\\sqrt 6\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(\\displaystyle\\frac{2(x + 5)^{3/2}}{3}\\right) = (x + 5)^{1/2} = \\sqrt{x + 5}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(18 - 4\\sqrt 6\\)." } },
  { id: "y2in5-027", topicRef: "y2in5", topicTitle: "Integration by Substitution 27", difficulty: "Standard", questionText: "Use \\(u = e^x + 3\\) to evaluate \\( \\displaystyle\\int_0^{\\ln 2} \\displaystyle\\frac{e^x}{e^x + 3}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x)\\;\\Rightarrow\\;du = g'(x)\\,dx", explanation: "Standard u-substitution." }, { stepNumber: 2, description: "Spot the \\(f'/f\\) form.", workingLatex: "\\displaystyle\\frac{d}{dx}(e^x + 3) = e^x", explanation: "Numerator is the derivative of the denominator." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = e^x + 3 \\;\\Rightarrow\\; du = e^x\\,dx", explanation: "Denominator as \\(u\\)." }, { stepNumber: 4, description: "Convert the limits.", workingLatex: "x = 0 \\Rightarrow u = 1 + 3 = 4,\\quad x = \\ln 2 \\Rightarrow u = 2 + 3 = 5", explanation: "Use \\(e^{\\ln 2} = 2\\)." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int_0^{\\ln 2} \\displaystyle\\frac{e^x}{e^x + 3}\\,dx = \\displaystyle\\int_4^5 \\displaystyle\\frac{1}{u}\\,du", explanation: "The \\(e^x\\,dx\\) is exactly \\(du\\)." }, { stepNumber: 6, description: "Integrate in \\(u\\) and evaluate.", workingLatex: "\\left[\\ln u\\right]_4^5 = \\ln 5 - \\ln 4 = \\ln\\displaystyle\\frac{5}{4}", explanation: "\\(u > 0\\) on \\([4,5]\\) so modulus bars are unnecessary." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln(e^x + 3) = \\displaystyle\\frac{e^x}{e^x + 3}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln\\displaystyle\\frac{5}{4}\\)." } },
  // ── More practice ────
  { id: "y2in5-028", topicRef: "y2in5", topicTitle: "Integration by Substitution 28", difficulty: "Standard", questionText: "Use \\(u = 1 + \\sin x\\) to find \\( \\displaystyle\\int \\left(1 + \\sin x\\right)^3\\cos x\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x)\\;\\Rightarrow\\;du = g'(x)\\,dx", explanation: "Standard u-substitution." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(1 + \\sin x) = \\cos x", explanation: "\\(\\cos x\\,dx\\) is exactly the derivative bundle for \\(1 + \\sin x\\)." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 1 + \\sin x \\;\\Rightarrow\\; du = \\cos x\\,dx", explanation: "Inner composite." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int (1 + \\sin x)^3\\cos x\\,dx = \\displaystyle\\int u^3\\,du", explanation: "Bundle \\(\\cos x\\,dx = du\\)." }, { stepNumber: 5, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int u^3\\,du = \\displaystyle\\frac{u^4}{4} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{(1 + \\sin x)^4}{4} + C", explanation: "Replace \\(u\\) by \\(1 + \\sin x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(\\displaystyle\\frac{(1 + \\sin x)^4}{4}\\right) = (1 + \\sin x)^3\\cos x\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(1 + \\sin x)^4}{4} + C\\)." } },
  { id: "y2in5-029", topicRef: "y2in5", topicTitle: "Integration by Substitution 29", difficulty: "Standard", questionText: "Use \\(u = x^2 + 2x\\) to find \\( \\displaystyle\\int \\left(x + 1\\right)\\left(x^2 + 2x\\right)^4\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x)\\;\\Rightarrow\\;du = g'(x)\\,dx", explanation: "Standard u-substitution." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(x^2 + 2x) = 2x + 2 = 2(x + 1)", explanation: "Outside factor \\((x + 1)\\) is half the derivative of the inner function." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = x^2 + 2x \\;\\Rightarrow\\; du = 2(x + 1)\\,dx \\;\\Rightarrow\\; (x + 1)\\,dx = \\displaystyle\\frac{du}{2}", explanation: "Rearrange for the bundle \\((x + 1)\\,dx\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int (x + 1)(x^2 + 2x)^4\\,dx = \\displaystyle\\int u^4 \\cdot \\displaystyle\\frac{du}{2} = \\displaystyle\\frac{1}{2}\\displaystyle\\int u^4\\,du", explanation: "Substitute and pull out the constant." }, { stepNumber: 5, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int u^4\\,du = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{u^5}{5} + C = \\displaystyle\\frac{u^5}{10} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{(x^2 + 2x)^5}{10} + C", explanation: "Replace \\(u\\) by \\(x^2 + 2x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(\\displaystyle\\frac{(x^2 + 2x)^5}{10}\\right) = \\displaystyle\\frac{5(x^2 + 2x)^4 \\cdot (2x + 2)}{10} = (x + 1)(x^2 + 2x)^4\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(x^2 + 2x)^5}{10} + C\\)." } },
  { id: "y2in5-030", topicRef: "y2in5", topicTitle: "Integration by Substitution 30", difficulty: "Standard", questionText: "Use \\(u = \\cos x\\) to find \\( \\displaystyle\\int \\tan x\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite \\(\\tan x\\) in sine/cosine form.", workingLatex: "\\tan x = \\displaystyle\\frac{\\sin x}{\\cos x}", explanation: "Expose the \\(f'/f\\) structure (up to sign)." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}\\cos x = -\\sin x", explanation: "Numerator is, up to a sign, the derivative of the denominator." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\cos x \\;\\Rightarrow\\; du = -\\sin x\\,dx \\;\\Rightarrow\\; \\sin x\\,dx = -du", explanation: "Solve for the numerator bundle." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\sin x}{\\cos x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{-du}{u} = -\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "Substitute." }, { stepNumber: 5, description: "Integrate in \\(u\\).", workingLatex: "-\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du = -\\ln|u| + C", explanation: "Standard log antiderivative." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= -\\ln|\\cos x| + C", explanation: "Replace \\(u\\) by \\(\\cos x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(-\\ln|\\cos x|\\right) = -\\displaystyle\\frac{-\\sin x}{\\cos x} = \\tan x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(-\\ln|\\cos x| + C\\)." } },
  { id: "y2in5-031", topicRef: "y2in5", topicTitle: "Integration by Substitution 31", difficulty: "Standard", questionText: "Use \\(u = \\sin x\\) to find \\( \\displaystyle\\int \\cot x\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite \\(\\cot x\\) in sine/cosine form.", workingLatex: "\\cot x = \\displaystyle\\frac{\\cos x}{\\sin x}", explanation: "Expose the \\(f'/f\\) structure." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}\\sin x = \\cos x", explanation: "Numerator is exactly the derivative of the denominator." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\sin x \\;\\Rightarrow\\; du = \\cos x\\,dx", explanation: "Bundle \\(\\cos x\\,dx = du\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\cos x}{\\sin x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "Direct substitution." }, { stepNumber: 5, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du = \\ln|u| + C", explanation: "Standard log antiderivative." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\ln|\\sin x| + C", explanation: "Replace \\(u\\) by \\(\\sin x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln|\\sin x| = \\displaystyle\\frac{\\cos x}{\\sin x} = \\cot x\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|\\sin x| + C\\)." } },
  { id: "y2in5-032", topicRef: "y2in5", topicTitle: "Integration by Substitution 32", difficulty: "Foundation", questionText: "Use \\(u = 2 - 3x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{1}{2 - 3x}\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 2 - 3x \\;\\Rightarrow\\; du = -3\\,dx \\;\\Rightarrow\\; dx = -\\displaystyle\\frac{du}{3}", explanation: "Linear substitution; rearrange for \\(dx\\)." }, { stepNumber: 2, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{2 - 3x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\cdot\\left(-\\displaystyle\\frac{1}{3}\\right)du = -\\displaystyle\\frac{1}{3}\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "Pull the constant out front." }, { stepNumber: 3, description: "Integrate in \\(u\\).", workingLatex: "-\\displaystyle\\frac{1}{3}\\ln|u| + C", explanation: "Standard log antiderivative." }, { stepNumber: 4, description: "Back-substitute.", workingLatex: "= -\\displaystyle\\frac{1}{3}\\ln|2 - 3x| + C", explanation: "Replace \\(u\\) by \\(2 - 3x\\)." }, { stepNumber: 5, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(-\\displaystyle\\frac{1}{3}\\ln|2 - 3x|\\right) = -\\displaystyle\\frac{1}{3}\\cdot\\displaystyle\\frac{-3}{2 - 3x} = \\displaystyle\\frac{1}{2 - 3x}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{1}{3}\\ln|2 - 3x| + C\\)." } },
  { id: "y2in5-033", topicRef: "y2in5", topicTitle: "Integration by Substitution 33", difficulty: "Standard", questionText: "Use \\(u = x^2 - 9\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{x}{x^2 - 9}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot the \\(f'/f\\) pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(x^2 - 9) = 2x", explanation: "Numerator \\(x\\) is half the derivative of the denominator." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = x^2 - 9 \\;\\Rightarrow\\; du = 2x\\,dx \\;\\Rightarrow\\; x\\,dx = \\displaystyle\\frac{du}{2}", explanation: "Rearrange for the numerator bundle." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{x^2 - 9}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\cdot\\displaystyle\\frac{du}{2} = \\displaystyle\\frac{1}{2}\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "Constant pulled out." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\frac{1}{2}\\ln|u| + C", explanation: "Standard log antiderivative." }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln|x^2 - 9| + C", explanation: "Replace \\(u\\) by \\(x^2 - 9\\). Bars retained since \\(x^2 - 9\\) changes sign across \\(x = \\pm 3\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(\\displaystyle\\frac{1}{2}\\ln|x^2 - 9|\\right) = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{2x}{x^2 - 9} = \\displaystyle\\frac{x}{x^2 - 9}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln|x^2 - 9| + C\\)." } },
  { id: "y2in5-034", topicRef: "y2in5", topicTitle: "Integration by Substitution 34", difficulty: "Challenge", questionText: "Use \\(u = e^x - 1\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{e^x}{\\sqrt{e^x - 1}}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x)\\;\\Rightarrow\\;du = g'(x)\\,dx", explanation: "Standard u-substitution." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(e^x - 1) = e^x", explanation: "Numerator \\(e^x\\) is exactly the derivative of the inner function under the root." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = e^x - 1 \\;\\Rightarrow\\; du = e^x\\,dx", explanation: "Inner composite." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{e^x}{\\sqrt{e^x - 1}}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{\\sqrt u}\\,du = \\displaystyle\\int u^{-1/2}\\,du", explanation: "Bundle \\(e^x\\,dx = du\\); rewrite in index form." }, { stepNumber: 5, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int u^{-1/2}\\,du = 2u^{1/2} + C", explanation: "Power rule: index goes from \\(-\\displaystyle\\frac{1}{2}\\) to \\(\\displaystyle\\frac{1}{2}\\), divide by \\(\\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= 2\\sqrt{e^x - 1} + C", explanation: "Replace \\(u\\) by \\(e^x - 1\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(2\\sqrt{e^x - 1}\\right) = 2\\cdot\\displaystyle\\frac{e^x}{2\\sqrt{e^x - 1}} = \\displaystyle\\frac{e^x}{\\sqrt{e^x - 1}}\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(2\\sqrt{e^x - 1} + C\\)." } },
  { id: "y2in5-035", topicRef: "y2in5", topicTitle: "Integration by Substitution 35", difficulty: "Foundation", questionText: "Use \\(u = 3x + 1\\) to find \\( \\displaystyle\\int \\left(3x + 1\\right)^{\\tfrac{1}{3}}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 3x + 1 \\;\\Rightarrow\\; du = 3\\,dx \\;\\Rightarrow\\; dx = \\displaystyle\\frac{du}{3}", explanation: "Linear substitution; rearrange for \\(dx\\)." }, { stepNumber: 2, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int (3x + 1)^{1/3}\\,dx = \\displaystyle\\int u^{1/3} \\cdot \\displaystyle\\frac{du}{3} = \\displaystyle\\frac{1}{3}\\displaystyle\\int u^{1/3}\\,du", explanation: "Pull the constant out front." }, { stepNumber: 3, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\frac{1}{3}\\displaystyle\\int u^{1/3}\\,du = \\displaystyle\\frac{1}{3} \\cdot \\displaystyle\\frac{u^{4/3}}{\\;4/3\\;} + C = \\displaystyle\\frac{u^{4/3}}{4} + C", explanation: "Power rule: divide by the new index \\(\\displaystyle\\frac{4}{3}\\)." }, { stepNumber: 4, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{(3x + 1)^{4/3}}{4} + C", explanation: "Replace \\(u\\) by \\(3x + 1\\)." }, { stepNumber: 5, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(\\displaystyle\\frac{(3x + 1)^{4/3}}{4}\\right) = \\displaystyle\\frac{1}{4}\\cdot\\displaystyle\\frac{4}{3}(3x + 1)^{1/3}\\cdot 3 = (3x + 1)^{1/3}\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(3x + 1)^{4/3}}{4} + C\\)." } },
  // ── More substitutions ────
  { id: "y2in5-036", topicRef: "y2in5", topicTitle: "Integration by Substitution 36", difficulty: "Standard", questionText: "Use \\(u = \\sec x\\) to find \\( \\displaystyle\\int \\sec^3 x\\tan x\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}\\sec x = \\sec x\\tan x", explanation: "The integrand has \\(\\sec^2 x\\) times the derivative of \\(\\sec x\\)." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\sec x \\;\\Rightarrow\\; du = \\sec x\\tan x\\,dx", explanation: "Bundle the awkward factor into \\(du\\)." }, { stepNumber: 3, description: "Restructure the integrand.", workingLatex: "\\sec^3 x\\tan x\\,dx = \\sec^2 x \\cdot (\\sec x\\tan x\\,dx) = u^2\\,du", explanation: "The remaining \\(\\sec^2 x = u^2\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\sec^3 x\\tan x\\,dx = \\displaystyle\\int u^2\\,du", explanation: "Clean power integral." }, { stepNumber: 5, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int u^2\\,du = \\displaystyle\\frac{u^3}{3} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{\\sec^3 x}{3} + C", explanation: "Replace \\(u\\) by \\(\\sec x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(\\displaystyle\\frac{\\sec^3 x}{3}\\right) = \\sec^2 x \\cdot \\sec x\\tan x = \\sec^3 x\\tan x\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{\\sec^3 x}{3} + C\\)." } },
  { id: "y2in5-037", topicRef: "y2in5", topicTitle: "Integration by Substitution 37", difficulty: "Standard", questionText: "Use \\(u = \\csc x\\) to find \\( \\displaystyle\\int \\csc^2 x\\cot x\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Switch to a cleaner choice of \\(u\\).", workingLatex: "u = \\cot x", explanation: "Letting \\(u = \\cot x\\) is more efficient than \\(u = \\csc x\\) because \\(\\displaystyle\\frac{d}{dx}\\cot x = -\\csc^2 x\\) absorbs the \\(\\csc^2 x\\,dx\\) bundle directly." }, { stepNumber: 2, description: "Compute \\(du\\).", workingLatex: "du = -\\csc^2 x\\,dx \\;\\Rightarrow\\; \\csc^2 x\\,dx = -du", explanation: "Rearrange for the integrand bundle." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\csc^2 x\\cot x\\,dx = \\displaystyle\\int u \\cdot (-du) = -\\displaystyle\\int u\\,du", explanation: "Substitute \\(\\cot x = u\\) and \\(\\csc^2 x\\,dx = -du\\)." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "-\\displaystyle\\int u\\,du = -\\displaystyle\\frac{u^2}{2} + C", explanation: "Power rule." }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= -\\displaystyle\\frac{\\cot^2 x}{2} + C", explanation: "Replace \\(u\\) by \\(\\cot x\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(-\\displaystyle\\frac{\\cot^2 x}{2}\\right) = -\\cot x \\cdot (-\\csc^2 x) = \\csc^2 x\\cot x\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{\\cot^2 x}{2} + C\\)." } },
  { id: "y2in5-038", topicRef: "y2in5", topicTitle: "Integration by Substitution 38", difficulty: "Standard", questionText: "Use \\(u = 2 - \\sin x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{\\cos x}{\\left(2 - \\sin x\\right)^3}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(2 - \\sin x) = -\\cos x", explanation: "The numerator \\(\\cos x\\) is (up to sign) the derivative of the denominator base." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 2 - \\sin x \\;\\Rightarrow\\; du = -\\cos x\\,dx \\;\\Rightarrow\\; \\cos x\\,dx = -du", explanation: "Rearrange for the numerator bundle." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\cos x}{(2 - \\sin x)^3}\\,dx = \\displaystyle\\int \\displaystyle\\frac{-du}{u^3} = -\\displaystyle\\int u^{-3}\\,du", explanation: "Bundle the bracket and \\(\\cos x\\,dx\\)." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "-\\displaystyle\\int u^{-3}\\,du = -\\displaystyle\\frac{u^{-2}}{-2} + C = \\displaystyle\\frac{1}{2u^2} + C", explanation: "Power rule with index \\(-3 \\to -2\\)." }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{1}{2(2 - \\sin x)^2} + C", explanation: "Replace \\(u\\) by \\(2 - \\sin x\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(\\displaystyle\\frac{1}{2(2 - \\sin x)^2}\\right) = \\displaystyle\\frac{1}{2}\\cdot(-2)(2 - \\sin x)^{-3}\\cdot(-\\cos x) = \\displaystyle\\frac{\\cos x}{(2 - \\sin x)^3}\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2(2 - \\sin x)^2} + C\\)." } },
  { id: "y2in5-039", topicRef: "y2in5", topicTitle: "Integration by Substitution 39", difficulty: "Standard", questionText: "Use \\(u = \\sqrt x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{e^{\\sqrt x}}{\\sqrt x}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}\\sqrt x = \\displaystyle\\frac{1}{2\\sqrt x}", explanation: "The factor \\(\\displaystyle\\frac{1}{\\sqrt x}\\,dx\\) is, up to a constant, the derivative of \\(\\sqrt x\\)." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\sqrt x \\;\\Rightarrow\\; du = \\displaystyle\\frac{1}{2\\sqrt x}\\,dx \\;\\Rightarrow\\; \\displaystyle\\frac{dx}{\\sqrt x} = 2\\,du", explanation: "Rearrange for the awkward \\(\\displaystyle\\frac{dx}{\\sqrt x}\\) bundle." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{e^{\\sqrt x}}{\\sqrt x}\\,dx = \\displaystyle\\int e^u \\cdot 2\\,du = 2\\displaystyle\\int e^u\\,du", explanation: "Substitute \\(e^{\\sqrt x} = e^u\\) and bundle." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "2\\displaystyle\\int e^u\\,du = 2e^u + C", explanation: "Exponential antiderivative." }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= 2e^{\\sqrt x} + C", explanation: "Replace \\(u\\) by \\(\\sqrt x\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(2e^{\\sqrt x}\\right) = 2e^{\\sqrt x}\\cdot\\displaystyle\\frac{1}{2\\sqrt x} = \\displaystyle\\frac{e^{\\sqrt x}}{\\sqrt x}\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(2e^{\\sqrt x} + C\\)." } },
  { id: "y2in5-040", topicRef: "y2in5", topicTitle: "Integration by Substitution 40", difficulty: "Standard", questionText: "Use \\(u = \\ln x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{\\cos(\\ln x)}{x}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln x = \\displaystyle\\frac{1}{x}", explanation: "The integrand has a function of \\(\\ln x\\) multiplied by its derivative." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\ln x \\;\\Rightarrow\\; du = \\displaystyle\\frac{1}{x}\\,dx", explanation: "Inner composite." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\cos(\\ln x)}{x}\\,dx = \\displaystyle\\int \\cos u\\,du", explanation: "Bundle \\(\\displaystyle\\frac{dx}{x} = du\\); \\(\\cos(\\ln x) = \\cos u\\)." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int \\cos u\\,du = \\sin u + C", explanation: "Standard trig antiderivative." }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= \\sin(\\ln x) + C", explanation: "Replace \\(u\\) by \\(\\ln x\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\sin(\\ln x) = \\cos(\\ln x) \\cdot \\displaystyle\\frac{1}{x} = \\displaystyle\\frac{\\cos(\\ln x)}{x}\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\sin(\\ln x) + C\\)." } },
  { id: "y2in5-041", topicRef: "y2in5", topicTitle: "Integration by Substitution 41", difficulty: "Foundation", questionText: "Use \\(u = e^x + 2\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{e^x}{e^x + 2}\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot the \\(f'/f\\) pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(e^x + 2) = e^x", explanation: "Numerator is exactly the derivative of the denominator." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = e^x + 2 \\;\\Rightarrow\\; du = e^x\\,dx", explanation: "Bundle \\(e^x\\,dx = du\\)." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{e^x}{e^x + 2}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "Direct substitution." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du = \\ln|u| + C", explanation: "Standard log antiderivative." }, { stepNumber: 5, description: "Back-substitute and drop modulus.", workingLatex: "= \\ln(e^x + 2) + C", explanation: "Since \\(e^x > 0\\) we have \\(e^x + 2 > 0\\), so bars are unnecessary." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln(e^x + 2) = \\displaystyle\\frac{e^x}{e^x + 2}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln(e^x + 2) + C\\)." } },
  { id: "y2in5-042", topicRef: "y2in5", topicTitle: "Integration by Substitution 42", difficulty: "Standard", questionText: "Use \\(u = \\sin(2x)\\) to find \\( \\displaystyle\\int \\cos(2x)\\sin^3\\left(2x\\right)\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}\\sin(2x) = 2\\cos(2x)", explanation: "Integrand has \\(\\sin^3(2x)\\) times (half) the derivative of \\(\\sin(2x)\\)." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\sin(2x) \\;\\Rightarrow\\; du = 2\\cos(2x)\\,dx \\;\\Rightarrow\\; \\cos(2x)\\,dx = \\displaystyle\\frac{du}{2}", explanation: "Rearrange for the bundle." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\cos(2x)\\sin^3(2x)\\,dx = \\displaystyle\\int u^3 \\cdot \\displaystyle\\frac{du}{2} = \\displaystyle\\frac{1}{2}\\displaystyle\\int u^3\\,du", explanation: "Pull the constant out front." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int u^3\\,du = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{u^4}{4} + C = \\displaystyle\\frac{u^4}{8} + C", explanation: "Power rule." }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{\\sin^4(2x)}{8} + C", explanation: "Replace \\(u\\) by \\(\\sin(2x)\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(\\displaystyle\\frac{\\sin^4(2x)}{8}\\right) = \\displaystyle\\frac{4\\sin^3(2x)\\cdot 2\\cos(2x)}{8} = \\cos(2x)\\sin^3(2x)\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{\\sin^4(2x)}{8} + C\\)." } },
  { id: "y2in5-043", topicRef: "y2in5", topicTitle: "Integration by Substitution 43", difficulty: "Standard", questionText: "Use \\(u = 4 - x^2\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{x}{\\sqrt{4 - x^2}}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(4 - x^2) = -2x", explanation: "Numerator \\(x\\) is (up to a constant) the derivative of the radicand." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 4 - x^2 \\;\\Rightarrow\\; du = -2x\\,dx \\;\\Rightarrow\\; x\\,dx = -\\displaystyle\\frac{du}{2}", explanation: "Rearrange for the numerator bundle." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{\\sqrt{4 - x^2}}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{\\sqrt u}\\cdot\\left(-\\displaystyle\\frac{du}{2}\\right) = -\\displaystyle\\frac{1}{2}\\displaystyle\\int u^{-1/2}\\,du", explanation: "Substitute and pull the constant out." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "-\\displaystyle\\frac{1}{2}\\displaystyle\\int u^{-1/2}\\,du = -\\displaystyle\\frac{1}{2}\\cdot 2u^{1/2} + C = -u^{1/2} + C", explanation: "Power rule." }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= -\\sqrt{4 - x^2} + C", explanation: "Replace \\(u\\) by \\(4 - x^2\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left(-\\sqrt{4 - x^2}\\right) = -\\displaystyle\\frac{-2x}{2\\sqrt{4 - x^2}} = \\displaystyle\\frac{x}{\\sqrt{4 - x^2}}\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(-\\sqrt{4 - x^2} + C\\)." } },
  { id: "y2in5-044", topicRef: "y2in5", topicTitle: "Integration by Substitution 44", difficulty: "Challenge", questionText: "Use \\(u = x^2 + 4\\) to find \\( \\displaystyle\\int x^3\\left(x^2 + 4\\right)^5\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the substitution and the leftover \\(x^2\\).", workingLatex: "u = x^2 + 4 \\;\\Rightarrow\\; x^2 = u - 4,\\; du = 2x\\,dx", explanation: "After absorbing one \\(x\\,dx\\) into \\(du\\), the leftover \\(x^2\\) must be written in terms of \\(u\\)." }, { stepNumber: 2, description: "Split the integrand.", workingLatex: "x^3(x^2 + 4)^5\\,dx = x^2 \\cdot (x^2 + 4)^5 \\cdot x\\,dx", explanation: "Isolate the \\(x\\,dx\\) bundle that pairs with \\(du\\)." }, { stepNumber: 3, description: "Convert each piece to \\(u\\).", workingLatex: "x^2 = u - 4,\\; (x^2 + 4)^5 = u^5,\\; x\\,dx = \\displaystyle\\frac{du}{2}", explanation: "All \\(x\\) pieces rewritten in \\(u\\)." }, { stepNumber: 4, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int x^3(x^2 + 4)^5\\,dx = \\displaystyle\\int (u - 4)u^5 \\cdot \\displaystyle\\frac{du}{2} = \\displaystyle\\frac{1}{2}\\displaystyle\\int (u^6 - 4u^5)\\,du", explanation: "Expand the product and pull out the \\(\\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 5, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\frac{1}{2}\\displaystyle\\int (u^6 - 4u^5)\\,du = \\displaystyle\\frac{1}{2}\\left(\\displaystyle\\frac{u^7}{7} - \\displaystyle\\frac{4u^6}{6}\\right) + C = \\displaystyle\\frac{u^7}{14} - \\displaystyle\\frac{u^6}{3} \\cdot \\displaystyle\\frac{2}{1} \\cdot \\displaystyle\\frac{1}{2}", explanation: "Power rule term by term; simplify the constants." }, { stepNumber: 6, description: "Simplify the constants.", workingLatex: "= \\displaystyle\\frac{u^7}{14} - \\displaystyle\\frac{2u^6}{3} + C", explanation: "\\(\\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{4}{6} = \\displaystyle\\frac{2}{6} = \\displaystyle\\frac{1}{3}\\), so the second term is \\(-\\displaystyle\\frac{1}{3}\\cdot 2u^6 = -\\displaystyle\\frac{2u^6}{3}\\)." }, { stepNumber: 7, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{(x^2 + 4)^7}{14} - \\displaystyle\\frac{2(x^2 + 4)^6}{3} + C", explanation: "Replace \\(u\\) by \\(x^2 + 4\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[\\displaystyle\\frac{(x^2 + 4)^7}{14} - \\displaystyle\\frac{2(x^2 + 4)^6}{3}\\right] = x(x^2 + 4)^6 - 4x(x^2 + 4)^5 = x(x^2 + 4)^5\\left[(x^2 + 4) - 4\\right] = x^3(x^2 + 4)^5\\;\\checkmark", explanation: "Chain rule; factor and simplify to recover the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(x^2 + 4)^7}{14} - \\displaystyle\\frac{2(x^2 + 4)^6}{3} + C\\)." } },
  { id: "y2in5-045", topicRef: "y2in5", topicTitle: "Integration by Substitution 45", difficulty: "Challenge", questionText: "Use \\(u = \\sqrt x + 1\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{1}{\\sqrt x + 1}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Choose \\(u\\) and invert.", workingLatex: "u = \\sqrt x + 1 \\;\\Rightarrow\\; \\sqrt x = u - 1 \\;\\Rightarrow\\; x = (u - 1)^2", explanation: "Express \\(x\\) in \\(u\\) so that \\(dx\\) can be written in \\(du\\)." }, { stepNumber: 2, description: "Compute \\(dx\\).", workingLatex: "dx = 2(u - 1)\\,du", explanation: "Differentiate \\(x = (u - 1)^2\\) with respect to \\(u\\)." }, { stepNumber: 3, description: "Rewrite the integral entirely in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{\\sqrt x + 1}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\cdot 2(u - 1)\\,du = \\displaystyle\\int \\displaystyle\\frac{2(u - 1)}{u}\\,du", explanation: "Substitute the denominator and the \\(dx\\)." }, { stepNumber: 4, description: "Split the rational integrand.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{2(u - 1)}{u}\\,du = \\displaystyle\\int \\left(2 - \\displaystyle\\frac{2}{u}\\right)du", explanation: "Long-divide: \\(\\displaystyle\\frac{2u - 2}{u} = 2 - \\displaystyle\\frac{2}{u}\\)." }, { stepNumber: 5, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int \\left(2 - \\displaystyle\\frac{2}{u}\\right)du = 2u - 2\\ln|u| + C", explanation: "Linear plus log antiderivative." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= 2(\\sqrt x + 1) - 2\\ln(\\sqrt x + 1) + C = 2\\sqrt x + 2 - 2\\ln(\\sqrt x + 1) + C", explanation: "Replace \\(u\\) by \\(\\sqrt x + 1\\). Note \\(\\sqrt x + 1 > 0\\), so the modulus drops." }, { stepNumber: 7, description: "Absorb the constant.", workingLatex: "= 2\\sqrt x - 2\\ln(\\sqrt x + 1) + C", explanation: "The constant \\(+2\\) is absorbed into \\(C\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[2\\sqrt x - 2\\ln(\\sqrt x + 1)\\right] = \\displaystyle\\frac{1}{\\sqrt x} - \\displaystyle\\frac{2 \\cdot \\frac{1}{2\\sqrt x}}{\\sqrt x + 1} = \\displaystyle\\frac{1}{\\sqrt x} - \\displaystyle\\frac{1}{\\sqrt x(\\sqrt x + 1)} = \\displaystyle\\frac{(\\sqrt x + 1) - 1}{\\sqrt x(\\sqrt x + 1)} = \\displaystyle\\frac{1}{\\sqrt x + 1}\\;\\checkmark", explanation: "Combine into a single fraction; recovers the integrand." } ], finalAnswer: "\\(2\\sqrt x - 2\\ln(\\sqrt x + 1) + C\\)." } },
  { id: "y2in5-046", topicRef: "y2in5", topicTitle: "Integration by Substitution 46", difficulty: "Standard", questionText: "Use an appropriate substitution to find \\( \\displaystyle\\int \\displaystyle\\frac{\\sin x\\cos x}{\\sin^2 x + 1}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot the \\(f'/f\\) pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(\\sin^2 x + 1) = 2\\sin x\\cos x", explanation: "Numerator is half the derivative of the denominator — \\(f'/f\\) form." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\sin^2 x + 1 \\;\\Rightarrow\\; du = 2\\sin x\\cos x\\,dx \\;\\Rightarrow\\; \\sin x\\cos x\\,dx = \\displaystyle\\frac{du}{2}", explanation: "Denominator as \\(u\\); rearrange for the numerator bundle." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\sin x\\cos x}{\\sin^2 x + 1}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{u}\\cdot\\displaystyle\\frac{du}{2} = \\displaystyle\\frac{1}{2}\\displaystyle\\int \\displaystyle\\frac{1}{u}\\,du", explanation: "Pull the constant out front." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\frac{1}{2}\\ln|u| + C", explanation: "Standard log antiderivative." }, { stepNumber: 5, description: "Back-substitute and drop modulus.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln(\\sin^2 x + 1) + C", explanation: "Since \\(\\sin^2 x + 1 \\ge 1 > 0\\), the modulus bars are unnecessary." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[\\displaystyle\\frac{1}{2}\\ln(\\sin^2 x + 1)\\right] = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{2\\sin x\\cos x}{\\sin^2 x + 1} = \\displaystyle\\frac{\\sin x\\cos x}{\\sin^2 x + 1}\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln(\\sin^2 x + 1) + C\\)." } },
  { id: "y2in5-047", topicRef: "y2in5", topicTitle: "Integration by Substitution 47", difficulty: "Standard", questionText: "Use \\(u = \\arctan x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{\\arctan x}{1 + x^2}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the derivative of \\(\\arctan\\).", workingLatex: "\\displaystyle\\frac{d}{dx}\\arctan x = \\displaystyle\\frac{1}{1 + x^2}", explanation: "The factor \\(\\displaystyle\\frac{dx}{1 + x^2}\\) is exactly the derivative bundle for \\(\\arctan x\\)." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\arctan x \\;\\Rightarrow\\; du = \\displaystyle\\frac{1}{1 + x^2}\\,dx", explanation: "Inner composite." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\arctan x}{1 + x^2}\\,dx = \\displaystyle\\int u\\,du", explanation: "Direct substitution." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int u\\,du = \\displaystyle\\frac{u^2}{2} + C", explanation: "Power rule." }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{(\\arctan x)^2}{2} + C", explanation: "Replace \\(u\\) by \\(\\arctan x\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[\\displaystyle\\frac{(\\arctan x)^2}{2}\\right] = \\arctan x \\cdot \\displaystyle\\frac{1}{1 + x^2} = \\displaystyle\\frac{\\arctan x}{1 + x^2}\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(\\arctan x)^2}{2} + C\\)." } },
  { id: "y2in5-048", topicRef: "y2in5", topicTitle: "Integration by Substitution 48", difficulty: "Standard", questionText: "Use \\(u = \\arcsin x\\) to find \\( \\displaystyle\\int \\displaystyle\\frac{\\arcsin x}{\\sqrt{1 - x^2}}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the derivative of \\(\\arcsin\\).", workingLatex: "\\displaystyle\\frac{d}{dx}\\arcsin x = \\displaystyle\\frac{1}{\\sqrt{1 - x^2}}", explanation: "The factor \\(\\displaystyle\\frac{dx}{\\sqrt{1 - x^2}}\\) is exactly the derivative bundle for \\(\\arcsin x\\)." }, { stepNumber: 2, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\arcsin x \\;\\Rightarrow\\; du = \\displaystyle\\frac{1}{\\sqrt{1 - x^2}}\\,dx", explanation: "Inner composite." }, { stepNumber: 3, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\arcsin x}{\\sqrt{1 - x^2}}\\,dx = \\displaystyle\\int u\\,du", explanation: "Direct substitution." }, { stepNumber: 4, description: "Integrate in \\(u\\).", workingLatex: "\\displaystyle\\int u\\,du = \\displaystyle\\frac{u^2}{2} + C", explanation: "Power rule." }, { stepNumber: 5, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{(\\arcsin x)^2}{2} + C", explanation: "Replace \\(u\\) by \\(\\arcsin x\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[\\displaystyle\\frac{(\\arcsin x)^2}{2}\\right] = \\arcsin x \\cdot \\displaystyle\\frac{1}{\\sqrt{1 - x^2}} = \\displaystyle\\frac{\\arcsin x}{\\sqrt{1 - x^2}}\\;\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(\\arcsin x)^2}{2} + C\\)." } },
  // ── Definite mixed ────
  { id: "y2in5-049", topicRef: "y2in5", topicTitle: "Integration by Substitution 49", difficulty: "Challenge", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/2} \\sin^5 x\\,dx \\) using \\(u = \\cos x\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "The standard u-substitution: replace an inner function and its derivative-times-dx by a clean integral in \\(u\\)." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\sin^5 x = \\sin x\\left(\\sin^2 x\\right)^2 = \\sin x\\left(1 - \\cos^2 x\\right)^2", explanation: "An odd power of \\(\\sin\\) always splits off one factor of \\(\\sin x\\) (which will become \\(-du\\)), leaving an even polynomial in \\(\\cos x\\). That is exactly the \\(f(\\cos x)\\cdot(\\cos x)'\\) shape u-sub eats." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = \\cos x \\;\\Rightarrow\\; du = -\\sin x\\,dx \\;\\Rightarrow\\; \\sin x\\,dx = -du", explanation: "The leftover \\(\\sin x\\,dx\\) is absorbed by \\(-du\\)." }, { stepNumber: 4, description: "Convert the limits.", workingLatex: "x = 0 \\Rightarrow u = 1,\\quad x = \\tfrac{\\pi}{2} \\Rightarrow u = 0", explanation: "Convert limits up-front so we never need to back-substitute." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "\\displaystyle\\int_0^{\\pi/2} \\sin^5 x\\,dx = \\displaystyle\\int_1^{0} \\left(1 - u^2\\right)^2\\,(-du) = \\displaystyle\\int_0^{1} \\left(1 - u^2\\right)^2\\,du", explanation: "The minus sign on \\(du\\) flips the limits back to the natural \\(0 \\to 1\\) order." }, { stepNumber: 6, description: "Expand and integrate.", workingLatex: "\\displaystyle\\int_0^{1} \\left(1 - 2u^2 + u^4\\right)\\,du = \\left[u - \\frac{2u^3}{3} + \\frac{u^5}{5}\\right]_0^{1}", explanation: "Binomial expansion, then term-by-term power rule." }, { stepNumber: 7, description: "Evaluate.", workingLatex: "= 1 - \\frac{2}{3} + \\frac{1}{5} = \\frac{15 - 10 + 3}{15} = \\frac{8}{15}", explanation: "Common denominator 15." }, { stepNumber: 8, description: "Sanity check.", workingLatex: "\\frac{d}{dx}\\!\\left[-\\cos x + \\frac{2\\cos^3 x}{3} - \\frac{\\cos^5 x}{5}\\right] = \\sin x - 2\\cos^2 x\\sin x + \\cos^4 x\\sin x = \\sin x\\left(1 - \\cos^2 x\\right)^2 = \\sin^5 x\\,\\checkmark", explanation: "Differentiating the indefinite antiderivative recovers the integrand exactly." } ], finalAnswer: "\\(\\displaystyle\\frac{8}{15}\\)." } },
  { id: "y2in5-050", topicRef: "y2in5", topicTitle: "Integration by Substitution 50", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\frac{x}{\\sqrt{1 + x^2}}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Standard u-substitution." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\text{Integrand} = \\displaystyle\\frac{x}{\\sqrt{1 + x^2}}", explanation: "The numerator \\(x\\) is — up to a factor of \\(2\\) — the derivative of the inside of the square root. Classic \\(f(g(x))g'(x)\\) shape." }, { stepNumber: 3, description: "Choose \\(u\\) and compute \\(du\\).", workingLatex: "u = 1 + x^2 \\;\\Rightarrow\\; du = 2x\\,dx \\;\\Rightarrow\\; x\\,dx = \\displaystyle\\frac{du}{2}", explanation: "Solve for the exact piece appearing in the integral." }, { stepNumber: 4, description: "Convert the limits.", workingLatex: "x = 0 \\Rightarrow u = 1,\\quad x = 1 \\Rightarrow u = 2", explanation: "Track the \\(u\\)-limits directly." }, { stepNumber: 5, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int_0^1 \\displaystyle\\frac{x}{\\sqrt{1 + x^2}}\\,dx = \\frac{1}{2}\\displaystyle\\int_1^2 u^{-\\frac{1}{2}}\\,du", explanation: "All \\(x\\)-dependence is now in \\(u\\)." }, { stepNumber: 6, description: "Integrate.", workingLatex: "= \\frac{1}{2}\\left[2u^{\\frac{1}{2}}\\right]_1^2 = \\left[\\sqrt u\\,\\right]_1^2", explanation: "Power rule: \\(\\displaystyle\\int u^{-1/2}\\,du = 2u^{1/2}\\)." }, { stepNumber: 7, description: "Evaluate.", workingLatex: "= \\sqrt 2 - 1", explanation: "Plug in the new limits." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\sqrt{1 + x^2}\\right] = \\displaystyle\\frac{2x}{2\\sqrt{1 + x^2}} = \\displaystyle\\frac{x}{\\sqrt{1 + x^2}}\\,\\checkmark", explanation: "Antiderivative differentiates back to the integrand." } ], finalAnswer: "\\(\\sqrt 2 - 1\\)." } },
  { id: "y2in5-051", topicRef: "y2in5", topicTitle: "Integration by Substitution 51", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^1 x^2\\left(x^3 + 1\\right)^3\\,dx \\) with \\(u = x^3 + 1\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Standard u-substitution." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\text{Integrand} = x^2\\left(x^3 + 1\\right)^3", explanation: "\\(x^2\\) is exactly \\(\\tfrac{1}{3}\\) of \\(\\displaystyle\\frac{d}{dx}(x^3 + 1)\\) — the classic inner-function-and-its-derivative set-up." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = x^3 + 1 \\;\\Rightarrow\\; du = 3x^2\\,dx \\;\\Rightarrow\\; x^2\\,dx = \\displaystyle\\frac{du}{3}", explanation: "Pre-rearrange so the piece \\(x^2\\,dx\\) appearing in the integral is ready to substitute." }, { stepNumber: 4, description: "New limits.", workingLatex: "x = 0 \\Rightarrow u = 1,\\quad x = 1 \\Rightarrow u = 2", explanation: "Convert limits to \\(u\\)-values." }, { stepNumber: 5, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int_0^1 x^2(x^3 + 1)^3\\,dx = \\frac{1}{3}\\displaystyle\\int_1^2 u^3\\,du", explanation: "Substitution complete." }, { stepNumber: 6, description: "Integrate.", workingLatex: "= \\frac{1}{3}\\left[\\frac{u^4}{4}\\right]_1^2 = \\frac{1}{12}\\left[u^4\\right]_1^2", explanation: "Power rule." }, { stepNumber: 7, description: "Evaluate.", workingLatex: "= \\frac{1}{12}(16 - 1) = \\frac{15}{12} = \\frac{5}{4}", explanation: "Arithmetic." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(x^3 + 1)^4}{12}\\right] = \\displaystyle\\frac{4(x^3 + 1)^3 \\cdot 3x^2}{12} = x^2(x^3 + 1)^3\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{5}{4}\\)." } },
  { id: "y2in5-052", topicRef: "y2in5", topicTitle: "Integration by Substitution 52", difficulty: "Challenge", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\pi/4} \\sin(2x)\\sqrt{1 - \\cos(2x)}\\,dx \\) using \\(u = 1 - \\cos 2x\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Standard u-substitution." }, { stepNumber: 2, description: "Why this substitution.", workingLatex: "\\displaystyle\\frac{d}{dx}(1 - \\cos 2x) = 2\\sin 2x", explanation: "The factor \\(\\sin(2x)\\) outside the root is — up to a constant — the derivative of \\(1 - \\cos 2x\\), the inside of the root. Clean u-sub set-up." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = 1 - \\cos 2x \\;\\Rightarrow\\; du = 2\\sin(2x)\\,dx \\;\\Rightarrow\\; \\sin(2x)\\,dx = \\displaystyle\\frac{du}{2}", explanation: "Rearrange for the exact piece appearing in the integrand." }, { stepNumber: 4, description: "Convert the limits.", workingLatex: "x = 0 \\Rightarrow u = 1 - \\cos 0 = 0,\\quad x = \\tfrac{\\pi}{4} \\Rightarrow u = 1 - \\cos\\tfrac{\\pi}{2} = 1", explanation: "Translate to \\(u\\)-limits directly." }, { stepNumber: 5, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int_0^{\\pi/4} \\sin(2x)\\sqrt{1 - \\cos 2x}\\,dx = \\frac{1}{2}\\displaystyle\\int_0^1 u^{\\frac{1}{2}}\\,du", explanation: "All \\(x\\)-dependence is gone." }, { stepNumber: 6, description: "Integrate.", workingLatex: "= \\frac{1}{2}\\left[\\frac{2u^{\\frac{3}{2}}}{3}\\right]_0^1 = \\frac{1}{3}\\left[u^{\\frac{3}{2}}\\right]_0^1", explanation: "Power rule." }, { stepNumber: 7, description: "Evaluate.", workingLatex: "= \\frac{1}{3}(1 - 0) = \\frac{1}{3}", explanation: "Plug in the limits." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(1 - \\cos 2x)^{\\frac{3}{2}}}{3}\\right] = \\displaystyle\\frac{1}{3}\\cdot\\displaystyle\\frac{3}{2}(1 - \\cos 2x)^{\\frac{1}{2}}\\cdot 2\\sin 2x = \\sin(2x)\\sqrt{1 - \\cos 2x}\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{3}\\)." } },
  { id: "y2in5-053", topicRef: "y2in5", topicTitle: "Integration by Substitution 53", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\frac{e^{2x}}{1 + e^{2x}}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Standard u-substitution." }, { stepNumber: 2, description: "Spot the log pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(1 + e^{2x}) = 2e^{2x}", explanation: "Numerator is half the derivative of the denominator — the integrand is essentially \\(\\tfrac{1}{2}\\cdot \\tfrac{f'}{f}\\)." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = 1 + e^{2x} \\;\\Rightarrow\\; du = 2e^{2x}\\,dx \\;\\Rightarrow\\; e^{2x}\\,dx = \\displaystyle\\frac{du}{2}", explanation: "Solve for the piece in the integrand." }, { stepNumber: 4, description: "New limits.", workingLatex: "x = 0 \\Rightarrow u = 2,\\quad x = 1 \\Rightarrow u = 1 + e^2", explanation: "Convert directly." }, { stepNumber: 5, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int_0^1 \\displaystyle\\frac{e^{2x}}{1 + e^{2x}}\\,dx = \\frac{1}{2}\\displaystyle\\int_2^{1 + e^2} \\displaystyle\\frac{du}{u}", explanation: "Direct \\(\\displaystyle\\int du/u\\)." }, { stepNumber: 6, description: "Integrate.", workingLatex: "= \\frac{1}{2}\\left[\\ln u\\right]_2^{1 + e^2} = \\frac{1}{2}\\left(\\ln(1 + e^2) - \\ln 2\\right)", explanation: "\\(\\displaystyle\\int du/u = \\ln|u|\\); both endpoints are positive so drop the bars." }, { stepNumber: 7, description: "Tidy.", workingLatex: "= \\frac{1}{2}\\ln\\!\\left(\\displaystyle\\frac{1 + e^2}{2}\\right)", explanation: "Combine using \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{2}\\ln(1 + e^{2x})\\right] = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{2e^{2x}}{1 + e^{2x}} = \\displaystyle\\frac{e^{2x}}{1 + e^{2x}}\\,\\checkmark", explanation: "Confirms the antiderivative." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln\\!\\left(\\displaystyle\\frac{1 + e^2}{2}\\right)\\)." } },
  { id: "y2in5-054", topicRef: "y2in5", topicTitle: "Integration by Substitution 54", difficulty: "Foundation", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\left(1 - x\\right)^{10}\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Replace the linear inside-function." }, { stepNumber: 2, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = 1 - x \\;\\Rightarrow\\; du = -\\,dx \\;\\Rightarrow\\; dx = -\\,du", explanation: "Simple linear substitution to kill the bracket." }, { stepNumber: 3, description: "Convert the limits.", workingLatex: "x = 0 \\Rightarrow u = 1,\\quad x = 1 \\Rightarrow u = 0", explanation: "The limits get swapped because \\(u\\) is decreasing in \\(x\\)." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int_0^1 (1 - x)^{10}\\,dx = \\displaystyle\\int_1^{0} u^{10}\\,(-du) = \\displaystyle\\int_0^1 u^{10}\\,du", explanation: "Flip the limits and absorb the minus sign." }, { stepNumber: 5, description: "Integrate and evaluate.", workingLatex: "= \\left[\\frac{u^{11}}{11}\\right]_0^1 = \\frac{1}{11}", explanation: "Power rule." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{(1 - x)^{11}}{11}\\right] = -\\displaystyle\\frac{11(1 - x)^{10}(-1)}{11} = (1 - x)^{10}\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{11}\\)." } },
  { id: "y2in5-055", topicRef: "y2in5", topicTitle: "Integration by Substitution 55", difficulty: "Foundation", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\frac{1}{\\left(x + 1\\right)^2}\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "Choose a linear substitution.", workingLatex: "u = x + 1 \\;\\Rightarrow\\; du = dx", explanation: "The cleanest possible u-sub: \\(du\\) equals \\(dx\\)." }, { stepNumber: 2, description: "Convert the limits.", workingLatex: "x = 0 \\Rightarrow u = 1,\\quad x = 1 \\Rightarrow u = 2", explanation: "Translate to \\(u\\)-limits." }, { stepNumber: 3, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int_0^1 \\displaystyle\\frac{1}{(x + 1)^2}\\,dx = \\displaystyle\\int_1^2 u^{-2}\\,du", explanation: "Plain power integral in \\(u\\)." }, { stepNumber: 4, description: "Integrate.", workingLatex: "= \\left[-u^{-1}\\right]_1^2 = -\\displaystyle\\frac{1}{2} - (-1)", explanation: "Power rule: \\(\\displaystyle\\int u^{-2}\\,du = -u^{-1}\\)." }, { stepNumber: 5, description: "Evaluate.", workingLatex: "= 1 - \\displaystyle\\frac{1}{2} = \\displaystyle\\frac{1}{2}", explanation: "Arithmetic." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{1}{x + 1}\\right] = \\displaystyle\\frac{1}{(x + 1)^2}\\,\\checkmark", explanation: "Quotient/chain rule confirms." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\)." } },
  // ── Applied ────
  { id: "y2in5-056", topicRef: "y2in5", topicTitle: "Integration by Substitution 56", difficulty: "Challenge", questionText: "Find the area under \\(y = x\\sqrt{x + 1}\\) from 0 to 3.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["area"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the area integral.", workingLatex: "A = \\displaystyle\\int_0^3 x\\sqrt{x + 1}\\,dx", explanation: "The curve is above the \\(x\\)-axis on \\([0, 3]\\), so area equals the definite integral." }, { stepNumber: 2, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub; here the outer \\(x\\) is not the derivative of the inside, so we must also express \\(x\\) in terms of \\(u\\)." }, { stepNumber: 3, description: "Choose \\(u\\), invert.", workingLatex: "u = x + 1 \\;\\Rightarrow\\; x = u - 1,\\;\\; du = dx", explanation: "Inverting lets us replace the outer \\(x\\) cleanly." }, { stepNumber: 4, description: "New limits.", workingLatex: "x = 0 \\Rightarrow u = 1,\\quad x = 3 \\Rightarrow u = 4", explanation: "Convert directly." }, { stepNumber: 5, description: "Rewrite the integral in \\(u\\).", workingLatex: "A = \\displaystyle\\int_1^4 (u - 1)\\sqrt u\\,du = \\displaystyle\\int_1^4 \\left(u^{\\frac{3}{2}} - u^{\\frac{1}{2}}\\right)du", explanation: "Expand using \\(\\sqrt u = u^{1/2}\\)." }, { stepNumber: 6, description: "Integrate term-by-term.", workingLatex: "= \\left[\\displaystyle\\frac{2u^{\\frac{5}{2}}}{5} - \\displaystyle\\frac{2u^{\\frac{3}{2}}}{3}\\right]_1^4", explanation: "Power rule on each piece." }, { stepNumber: 7, description: "Evaluate at \\(u = 4\\) and \\(u = 1\\).", workingLatex: "= \\left(\\displaystyle\\frac{2\\cdot 32}{5} - \\displaystyle\\frac{2\\cdot 8}{3}\\right) - \\left(\\displaystyle\\frac{2}{5} - \\displaystyle\\frac{2}{3}\\right) = \\displaystyle\\frac{64}{5} - \\displaystyle\\frac{16}{3} - \\displaystyle\\frac{2}{5} + \\displaystyle\\frac{2}{3}", explanation: "Use \\(4^{5/2} = 32\\) and \\(4^{3/2} = 8\\)." }, { stepNumber: 8, description: "Combine.", workingLatex: "= \\displaystyle\\frac{62}{5} - \\displaystyle\\frac{14}{3} = \\displaystyle\\frac{186 - 70}{15} = \\displaystyle\\frac{116}{15}", explanation: "Common denominator 15." }, { stepNumber: 9, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{2(x+1)^{\\frac{5}{2}}}{5} - \\displaystyle\\frac{2(x+1)^{\\frac{3}{2}}}{3}\\right] = (x+1)^{\\frac{3}{2}} - (x+1)^{\\frac{1}{2}} = (x+1)^{\\frac{1}{2}}\\!\\left((x+1) - 1\\right) = x\\sqrt{x+1}\\,\\checkmark", explanation: "Confirms the antiderivative." } ], finalAnswer: "\\(\\displaystyle\\frac{116}{15}\\)." } },
  { id: "y2in5-057", topicRef: "y2in5", topicTitle: "Integration by Substitution 57", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\frac{dx}{x\\sqrt{\\ln x}} \\) via \\(u = \\ln x\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\text{Integrand} = \\displaystyle\\frac{1}{\\sqrt{\\ln x}}\\cdot\\displaystyle\\frac{1}{x}", explanation: "The factor \\(1/x\\) is exactly \\(\\displaystyle\\frac{d}{dx}\\ln x\\) — that is the \\(g'(x)\\,dx\\) piece the rule wants." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = \\ln x \\;\\Rightarrow\\; du = \\displaystyle\\frac{dx}{x}", explanation: "The whole \\(dx/x\\) becomes a single \\(du\\)." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{x\\sqrt{\\ln x}}\\,dx = \\displaystyle\\int u^{-\\frac{1}{2}}\\,du", explanation: "Clean power integral." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= 2u^{\\frac{1}{2}} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= 2\\sqrt{\\ln x} + C", explanation: "Replace \\(u\\) with \\(\\ln x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[2(\\ln x)^{\\frac{1}{2}}\\right] = 2\\cdot\\displaystyle\\frac{1}{2}(\\ln x)^{-\\frac{1}{2}}\\cdot\\displaystyle\\frac{1}{x} = \\displaystyle\\frac{1}{x\\sqrt{\\ln x}}\\,\\checkmark", explanation: "Chain rule on \\((\\ln x)^{1/2}\\)." } ], finalAnswer: "\\(2\\sqrt{\\ln x} + C\\)." } },
  // ── More ────
  { id: "y2in5-058", topicRef: "y2in5", topicTitle: "Integration by Substitution 58", difficulty: "Standard", questionText: "Use \\(u = \\tan x\\) to find \\( \\displaystyle\\int \\tan^2 x\\sec^2 x\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int f(g(x))g'(x)\\,dx = \\displaystyle\\int f(u)\\,du", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\displaystyle\\frac{d}{dx}\\tan x = \\sec^2 x", explanation: "The integrand is a polynomial in \\(\\tan x\\) times \\(\\sec^2 x\\) — exactly \\(f(\\tan x)\\cdot(\\tan x)'\\)." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = \\tan x \\;\\Rightarrow\\; du = \\sec^2 x\\,dx", explanation: "The whole \\(\\sec^2 x\\,dx\\) collapses into \\(du\\)." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\tan^2 x \\sec^2 x\\,dx = \\displaystyle\\int u^2\\,du", explanation: "Pure power integral." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= \\displaystyle\\frac{u^3}{3} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{\\tan^3 x}{3} + C", explanation: "Return to \\(x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{\\tan^3 x}{3}\\right] = \\tan^2 x\\sec^2 x\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{\\tan^3 x}{3} + C\\)." } },
  { id: "y2in5-059", topicRef: "y2in5", topicTitle: "Integration by Substitution 59", difficulty: "Standard", questionText: "Use \\(u = \\cot x\\) to find \\( \\displaystyle\\int \\cot^2 x\\csc^2 x\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the substitution template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\displaystyle\\frac{d}{dx}\\cot x = -\\csc^2 x", explanation: "Integrand is a polynomial in \\(\\cot x\\) times \\(\\csc^2 x\\) — perfectly matched to \\(u = \\cot x\\) (with a sign to track)." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = \\cot x \\;\\Rightarrow\\; du = -\\csc^2 x\\,dx \\;\\Rightarrow\\; \\csc^2 x\\,dx = -du", explanation: "Solve for the piece appearing in the integrand." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\cot^2 x\\csc^2 x\\,dx = \\displaystyle\\int u^2(-du) = -\\displaystyle\\int u^2\\,du", explanation: "Substitution complete." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= -\\displaystyle\\frac{u^3}{3} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= -\\displaystyle\\frac{\\cot^3 x}{3} + C", explanation: "Return to \\(x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{\\cot^3 x}{3}\\right] = -\\cot^2 x\\cdot(-\\csc^2 x) = \\cot^2 x\\csc^2 x\\,\\checkmark", explanation: "Chain rule confirms." } ], finalAnswer: "\\(-\\displaystyle\\frac{\\cot^3 x}{3} + C\\)." } },
  { id: "y2in5-060", topicRef: "y2in5", topicTitle: "Integration by Substitution 60", difficulty: "Standard", questionText: "Use \\(u = 5 - 2x^2\\) to find \\( \\displaystyle\\int x(5 - 2x^2)^7\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\displaystyle\\frac{d}{dx}(5 - 2x^2) = -4x", explanation: "The outer factor \\(x\\) is a constant multiple of the derivative of the bracket." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = 5 - 2x^2 \\;\\Rightarrow\\; du = -4x\\,dx \\;\\Rightarrow\\; x\\,dx = -\\displaystyle\\frac{du}{4}", explanation: "Solve for the piece in the integrand." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int x(5 - 2x^2)^7\\,dx = -\\frac{1}{4}\\displaystyle\\int u^7\\,du", explanation: "Pure power integral." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= -\\frac{1}{4}\\cdot\\displaystyle\\frac{u^8}{8} + C = -\\displaystyle\\frac{u^8}{32} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= -\\displaystyle\\frac{(5 - 2x^2)^8}{32} + C", explanation: "Return to \\(x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{(5 - 2x^2)^8}{32}\\right] = -\\displaystyle\\frac{8(5 - 2x^2)^7\\cdot(-4x)}{32} = x(5 - 2x^2)^7\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{(5 - 2x^2)^8}{32} + C\\)." } },
  { id: "y2in5-061", topicRef: "y2in5", topicTitle: "Integration by Substitution 61", difficulty: "Standard", questionText: "Use \\(u = \\sin(3x)\\) to find \\( \\displaystyle\\int \\sin^2\\left(3x\\right)\\cos(3x)\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\displaystyle\\frac{d}{dx}\\sin(3x) = 3\\cos(3x)", explanation: "The trailing \\(\\cos(3x)\\) is a constant multiple of the derivative of the inner \\(\\sin(3x)\\)." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = \\sin(3x) \\;\\Rightarrow\\; du = 3\\cos(3x)\\,dx \\;\\Rightarrow\\; \\cos(3x)\\,dx = \\displaystyle\\frac{du}{3}", explanation: "Solve for the piece appearing in the integrand." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\sin^2(3x)\\cos(3x)\\,dx = \\frac{1}{3}\\displaystyle\\int u^2\\,du", explanation: "Power integral." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= \\frac{1}{3}\\cdot\\displaystyle\\frac{u^3}{3} + C = \\displaystyle\\frac{u^3}{9} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{\\sin^3(3x)}{9} + C", explanation: "Return to \\(x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{\\sin^3(3x)}{9}\\right] = \\displaystyle\\frac{3\\sin^2(3x)\\cdot 3\\cos(3x)}{9} = \\sin^2(3x)\\cos(3x)\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{\\sin^3(3x)}{9} + C\\)." } },
  { id: "y2in5-062", topicRef: "y2in5", topicTitle: "Integration by Substitution 62", difficulty: "Standard", questionText: "Use \\(u = 3x^2 - 1\\) to find \\( \\displaystyle\\int \\frac{x}{\\left(3x^2 - 1\\right)^5}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\displaystyle\\frac{d}{dx}(3x^2 - 1) = 6x", explanation: "The numerator \\(x\\) is a constant multiple of the derivative of the bracket." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = 3x^2 - 1 \\;\\Rightarrow\\; du = 6x\\,dx \\;\\Rightarrow\\; x\\,dx = \\displaystyle\\frac{du}{6}", explanation: "Solve for the piece appearing in the integrand." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{(3x^2 - 1)^5}\\,dx = \\frac{1}{6}\\displaystyle\\int u^{-5}\\,du", explanation: "Power integral." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= \\frac{1}{6}\\cdot\\displaystyle\\frac{u^{-4}}{-4} + C = -\\displaystyle\\frac{1}{24u^4} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= -\\displaystyle\\frac{1}{24(3x^2 - 1)^4} + C", explanation: "Return to \\(x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{(3x^2 - 1)^{-4}}{24}\\right] = -\\displaystyle\\frac{-4(3x^2 - 1)^{-5}\\cdot 6x}{24} = \\displaystyle\\frac{x}{(3x^2 - 1)^5}\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{1}{24(3x^2 - 1)^4} + C\\)." } },
  { id: "y2in5-063", topicRef: "y2in5", topicTitle: "Integration by Substitution 63", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\frac{e^x - e^{-x}}{e^x + e^{-x}}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx \\;\\Rightarrow\\; \\displaystyle\\int \\displaystyle\\frac{g'(x)}{g(x)}\\,dx = \\ln|g(x)| + C", explanation: "Standard u-sub; here the integrand has a \\(g'/g\\) shape." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(e^x + e^{-x}) = e^x - e^{-x}", explanation: "The numerator is exactly the derivative of the denominator — textbook log-rule." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = e^x + e^{-x} \\;\\Rightarrow\\; du = (e^x - e^{-x})\\,dx", explanation: "Whole numerator-times-\\(dx\\) becomes a single \\(du\\)." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{e^x - e^{-x}}{e^x + e^{-x}}\\,dx = \\displaystyle\\int \\displaystyle\\frac{du}{u}", explanation: "Reduces to the standard reciprocal integral." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= \\ln|u| + C", explanation: "\\(\\displaystyle\\int du/u = \\ln|u|\\)." }, { stepNumber: 6, description: "Back-substitute and drop bars.", workingLatex: "= \\ln\\!\\left(e^x + e^{-x}\\right) + C", explanation: "Since \\(e^x + e^{-x} > 0\\) for every real \\(x\\), the modulus bars are redundant." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\ln(e^x + e^{-x})\\right] = \\displaystyle\\frac{e^x - e^{-x}}{e^x + e^{-x}}\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\ln\\!\\left(e^x + e^{-x}\\right) + C\\)." } },
  { id: "y2in5-064", topicRef: "y2in5", topicTitle: "Integration by Substitution 64", difficulty: "Challenge", questionText: "Use \\(u = 1 + x^{\\tfrac{3}{2}}\\) to find \\( \\displaystyle\\int \\sqrt x(1 + x^{\\tfrac{3}{2}})^2\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left(1 + x^{\\frac{3}{2}}\\right) = \\displaystyle\\frac{3}{2}x^{\\frac{1}{2}} = \\displaystyle\\frac{3}{2}\\sqrt x", explanation: "The outer \\(\\sqrt x\\) is a constant multiple of the derivative of the bracket." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = 1 + x^{\\frac{3}{2}} \\;\\Rightarrow\\; du = \\displaystyle\\frac{3}{2}\\sqrt x\\,dx \\;\\Rightarrow\\; \\sqrt x\\,dx = \\displaystyle\\frac{2}{3}\\,du", explanation: "Solve for the piece appearing in the integrand." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\sqrt x\\,(1 + x^{\\frac{3}{2}})^2\\,dx = \\frac{2}{3}\\displaystyle\\int u^2\\,du", explanation: "All \\(x\\)-dependence is gone." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= \\frac{2}{3}\\cdot\\displaystyle\\frac{u^3}{3} + C = \\displaystyle\\frac{2u^3}{9} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{2(1 + x^{\\frac{3}{2}})^3}{9} + C", explanation: "Return to \\(x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{2(1 + x^{\\frac{3}{2}})^3}{9}\\right] = \\displaystyle\\frac{2\\cdot 3(1 + x^{\\frac{3}{2}})^2\\cdot\\tfrac{3}{2}\\sqrt x}{9} = \\sqrt x\\,(1 + x^{\\frac{3}{2}})^2\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{2(1 + x^{\\tfrac{3}{2}})^3}{9} + C\\)." } },
  { id: "y2in5-065", topicRef: "y2in5", topicTitle: "Integration by Substitution 65", difficulty: "Standard", questionText: "Use \\(u = \\sqrt{x^2 + 1}\\) to find \\( \\displaystyle\\int \\frac{x}{\\sqrt{x^2 + 1}}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Why this substitution.", workingLatex: "\\displaystyle\\frac{d}{dx}\\sqrt{x^2 + 1} = \\displaystyle\\frac{x}{\\sqrt{x^2 + 1}}", explanation: "Remarkably, the integrand is exactly the derivative of \\(u\\) itself — so the answer will be \\(u + C\\)." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = \\sqrt{x^2 + 1} \\;\\Rightarrow\\; du = \\displaystyle\\frac{x}{\\sqrt{x^2 + 1}}\\,dx", explanation: "The entire integrand-times-\\(dx\\) is exactly \\(du\\)." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{\\sqrt{x^2 + 1}}\\,dx = \\displaystyle\\int du", explanation: "Trivial integral remains." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= u + C", explanation: "\\(\\displaystyle\\int du = u + C\\)." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\sqrt{x^2 + 1} + C", explanation: "Return to \\(x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\sqrt{x^2 + 1}\\right] = \\displaystyle\\frac{2x}{2\\sqrt{x^2 + 1}} = \\displaystyle\\frac{x}{\\sqrt{x^2 + 1}}\\,\\checkmark", explanation: "Chain rule on \\((x^2 + 1)^{1/2}\\)." } ], finalAnswer: "\\(\\sqrt{x^2 + 1} + C\\)." } },
  { id: "y2in5-066", topicRef: "y2in5", topicTitle: "Integration by Substitution 66", difficulty: "Challenge", questionText: "Use \\(u = x + \\cos x\\) to find \\( \\displaystyle\\int \\left(1 - \\sin x\\right)\\left(x + \\cos x\\right)^5\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Why u-sub here.", workingLatex: "\\displaystyle\\frac{d}{dx}(x + \\cos x) = 1 - \\sin x", explanation: "The factor \\((1 - \\sin x)\\) is exactly the derivative of the bracket — clean \\(f(u)\\,du\\) shape." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = x + \\cos x \\;\\Rightarrow\\; du = (1 - \\sin x)\\,dx", explanation: "Whole \\((1 - \\sin x)\\,dx\\) collapses to \\(du\\)." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int (1 - \\sin x)(x + \\cos x)^5\\,dx = \\displaystyle\\int u^5\\,du", explanation: "Pure power integral." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= \\displaystyle\\frac{u^6}{6} + C", explanation: "Power rule." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\displaystyle\\frac{(x + \\cos x)^6}{6} + C", explanation: "Return to \\(x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{(x + \\cos x)^6}{6}\\right] = (x + \\cos x)^5(1 - \\sin x)\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{(x + \\cos x)^6}{6} + C\\)." } },
  { id: "y2in5-067", topicRef: "y2in5", topicTitle: "Integration by Substitution 67", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\frac{\\sec^2 x}{1 + \\tan x}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Log-form of the reverse chain rule — applies whenever the numerator equals the derivative of the denominator." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(1 + \\tan x) = \\sec^2 x", explanation: "Numerator equals the derivative of the denominator exactly." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = 1 + \\tan x \\;\\Rightarrow\\; du = \\sec^2 x\\,dx", explanation: "Substitution lines up perfectly." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{\\sec^2 x}{1 + \\tan x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{du}{u}", explanation: "Standard reciprocal integral." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= \\ln|u| + C", explanation: "\\(\\displaystyle\\int du/u = \\ln|u|\\)." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\ln|1 + \\tan x| + C", explanation: "Keep modulus bars: \\(1 + \\tan x\\) does change sign across the domain." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\ln|1 + \\tan x|\\right] = \\displaystyle\\frac{\\sec^2 x}{1 + \\tan x}\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\ln|1 + \\tan x| + C\\)." } },
  { id: "y2in5-068", topicRef: "y2in5", topicTitle: "Integration by Substitution 68", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\frac{1}{x\\ln x}\\,dx \\) using \\(u = \\ln x\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\text{Integrand} = \\displaystyle\\frac{1}{\\ln x}\\cdot\\displaystyle\\frac{1}{x}", explanation: "The factor \\(1/x\\) is the derivative of \\(\\ln x\\); the remaining \\(1/\\ln x\\) is the reciprocal of \\(u\\). Classic \\(\\displaystyle\\int du/u\\)." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = \\ln x \\;\\Rightarrow\\; du = \\displaystyle\\frac{dx}{x}", explanation: "\\(dx/x\\) collapses to a single \\(du\\)." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{x\\ln x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{du}{u}", explanation: "Reduces to the standard reciprocal integral." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= \\ln|u| + C", explanation: "Direct antiderivative." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\ln|\\ln x| + C", explanation: "Keep modulus bars: \\(\\ln x\\) is negative for \\(0 < x < 1\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\ln|\\ln x|\\right] = \\displaystyle\\frac{1}{\\ln x}\\cdot\\displaystyle\\frac{1}{x} = \\displaystyle\\frac{1}{x\\ln x}\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\ln|\\ln x| + C\\)." } },
  { id: "y2in5-069", topicRef: "y2in5", topicTitle: "Integration by Substitution 69", difficulty: "Challenge", questionText: "Use \\(u = \\ln x\\) to transform \\( \\displaystyle\\int \\sin(\\ln x)\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub; here we invert because the outer factor isn't the derivative of the inner function." }, { stepNumber: 2, description: "Choose \\(u\\), invert.", workingLatex: "u = \\ln x \\;\\Rightarrow\\; x = e^u,\\;\\; dx = e^u\\,du", explanation: "Invert to write \\(dx\\) in terms of \\(du\\); the integrand had no spare \\(1/x\\), so we need the inverse form." }, { stepNumber: 3, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\sin(\\ln x)\\,dx = \\displaystyle\\int \\sin u\\,e^u\\,du = \\displaystyle\\int e^u\\sin u\\,du", explanation: "A clean integration-by-parts integral remains. The substitution has done its job." }, { stepNumber: 4, description: "Integration by parts — set up the standard \\(\\displaystyle\\int e^u \\sin u\\,du\\).", workingLatex: "I = \\displaystyle\\int e^u\\sin u\\,du,\\quad J = \\displaystyle\\int e^u\\cos u\\,du", explanation: "Two IBP applications produce a system in \\(I\\) and \\(J\\)." }, { stepNumber: 5, description: "Apply IBP twice.", workingLatex: "I = e^u\\sin u - J,\\quad J = e^u\\cos u + I", explanation: "First IBP on \\(I\\) with \\(v = \\sin u, dw = e^u du\\); second on \\(J\\) with \\(v = \\cos u, dw = e^u du\\)." }, { stepNumber: 6, description: "Solve the linear system.", workingLatex: "I = e^u\\sin u - (e^u\\cos u + I) \\;\\Rightarrow\\; 2I = e^u(\\sin u - \\cos u)", explanation: "Substitute \\(J\\) into the equation for \\(I\\)." }, { stepNumber: 7, description: "Solve for \\(I\\).", workingLatex: "I = \\displaystyle\\frac{e^u}{2}\\left(\\sin u - \\cos u\\right) + C", explanation: "Divide by 2 and add the constant." }, { stepNumber: 8, description: "Back-substitute \\(u = \\ln x\\), \\(e^u = x\\).", workingLatex: "\\displaystyle\\int \\sin(\\ln x)\\,dx = \\displaystyle\\frac{x}{2}\\left(\\sin(\\ln x) - \\cos(\\ln x)\\right) + C", explanation: "Return to the original variable." }, { stepNumber: 9, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{x}{2}(\\sin(\\ln x) - \\cos(\\ln x))\\right] = \\displaystyle\\frac{1}{2}(\\sin(\\ln x) - \\cos(\\ln x)) + \\displaystyle\\frac{1}{2}(\\cos(\\ln x) + \\sin(\\ln x)) = \\sin(\\ln x)\\,\\checkmark", explanation: "Product rule on the first part; chain rule produces the \\(1/x\\) which cancels the outer \\(x/2\\), giving \\(\\tfrac{1}{2}\\cos(\\ln x) + \\tfrac{1}{2}\\sin(\\ln x)\\) from the second bracket. Sum simplifies to \\(\\sin(\\ln x)\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{x}{2}(\\sin(\\ln x) - \\cos(\\ln x)) + C\\)." } },
  { id: "y2in5-070", topicRef: "y2in5", topicTitle: "Integration by Substitution 70", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\frac{6x^2 - 3}{2x^3 - 3x}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{f'(x)}{f(x)}\\,dx = \\ln|f(x)| + C", explanation: "Log-form of the reverse chain rule." }, { stepNumber: 2, description: "Spot the pattern.", workingLatex: "\\displaystyle\\frac{d}{dx}(2x^3 - 3x) = 6x^2 - 3", explanation: "Numerator is exactly the derivative of the denominator — no constant adjustment needed." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = 2x^3 - 3x \\;\\Rightarrow\\; du = (6x^2 - 3)\\,dx", explanation: "Numerator-times-\\(dx\\) is exactly \\(du\\)." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{6x^2 - 3}{2x^3 - 3x}\\,dx = \\displaystyle\\int \\displaystyle\\frac{du}{u}", explanation: "Standard reciprocal integral remains." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= \\ln|u| + C", explanation: "Direct antiderivative." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= \\ln|2x^3 - 3x| + C", explanation: "Keep modulus bars: \\(2x^3 - 3x = x(2x^2 - 3)\\) does change sign." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\ln|2x^3 - 3x|\\right] = \\displaystyle\\frac{6x^2 - 3}{2x^3 - 3x}\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(\\ln|2x^3 - 3x| + C\\)." } },
  { id: "y2in5-071", topicRef: "y2in5", topicTitle: "Integration by Substitution 71", difficulty: "Challenge", questionText: "Use \\(u = x^{\\tfrac{1}{3}}\\) to find \\( \\displaystyle\\int \\frac{1}{x^{\\tfrac{2}{3}}\\left(1 + x^{\\tfrac{1}{3}}\\right)}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["substitution"], workedSolution: { steps: [ { stepNumber: 1, description: "State the template.", workingLatex: "u = g(x) \\;\\Rightarrow\\; du = g'(x)\\,dx", explanation: "Standard u-sub." }, { stepNumber: 2, description: "Why this substitution.", workingLatex: "\\displaystyle\\frac{d}{dx}\\,x^{\\frac{1}{3}} = \\displaystyle\\frac{1}{3}x^{-\\frac{2}{3}}", explanation: "The factor \\(x^{-2/3}\\) in the integrand is a constant multiple of \\(\\displaystyle\\frac{d}{dx}x^{1/3}\\) — the rest of the integrand is a function of \\(x^{1/3}\\) alone." }, { stepNumber: 3, description: "Choose \\(u\\), compute \\(du\\).", workingLatex: "u = x^{\\frac{1}{3}} \\;\\Rightarrow\\; du = \\displaystyle\\frac{1}{3}x^{-\\frac{2}{3}}\\,dx \\;\\Rightarrow\\; \\displaystyle\\frac{dx}{x^{\\frac{2}{3}}} = 3\\,du", explanation: "Solve for the piece \\(dx/x^{2/3}\\) that appears in the integrand." }, { stepNumber: 4, description: "Rewrite in \\(u\\).", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{x^{\\frac{2}{3}}(1 + x^{\\frac{1}{3}})}\\,dx = \\displaystyle\\int \\displaystyle\\frac{1}{1 + u}\\cdot 3\\,du = 3\\displaystyle\\int \\displaystyle\\frac{du}{1 + u}", explanation: "A clean log-form integral remains." }, { stepNumber: 5, description: "Integrate.", workingLatex: "= 3\\ln|1 + u| + C", explanation: "Standard \\(\\displaystyle\\int du/(1+u) = \\ln|1+u|\\)." }, { stepNumber: 6, description: "Back-substitute.", workingLatex: "= 3\\ln|1 + x^{\\frac{1}{3}}| + C", explanation: "Return to \\(x\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[3\\ln|1 + x^{\\frac{1}{3}}|\\right] = \\displaystyle\\frac{3\\cdot\\tfrac{1}{3}x^{-\\frac{2}{3}}}{1 + x^{\\frac{1}{3}}} = \\displaystyle\\frac{1}{x^{\\frac{2}{3}}(1 + x^{\\frac{1}{3}})}\\,\\checkmark", explanation: "Chain rule recovers the integrand." } ], finalAnswer: "\\(3\\ln|1 + x^{\\tfrac{1}{3}}| + C\\)." } },
];
